            if (legalDocument === 'terms') {
              setTermsAccepted(false);
            } else if (legalDocument === 'privacy') {
              setPrivacyAccepted(false);
            }
            setLegalDocument(null);
          }}
        />
      </View>
    </KeyboardAvoidingView>
  );
}

