const equivalents: Record<string, string> = {
  a: '[a@4*]', b: '[b8]', e: '[e3*]', g: '[g9]', i: '[i1!|*]',
  o: '[o0*]', s: '[s$5]', t: '[t7+]', u: '[u*v]',
};
const separator = '[.*_~!@#$%^&+|/\\\\-]{0,3}';
const letters = (word: string, joiner: string) => [...word].map(c => (equivalents[c] || c) + '{1,8}').join(joiner);
const patterns = rules.terms.flatMap(term => [
  term.split(' ').map(word => letters(word, separator)).join('(?:\\s{1,3}|' + separator + ')'),
  // Spaces inside a word require separators between every letter: "put a bag" is ordinary English.
  letters(term.replace(/ /g, ''), '[\\s.*_~!@#$%^&+|/\\\\-]{1,3}'),
]);
const pattern = new RegExp('(^|[^a-z0-9])(?:' + patterns.join('|') + ')(?=$|[^a-z0-9])', 'i');

/** Advisory only: no contextual judgment, substring matching, or automatic penalties. */
export function containsOffensiveLanguage(text: string | null | undefined): boolean {
  const content = (text || '').replace(/^> \[[^\n]*\]: ([^\n]*)\n\n([\s\S]*)$/, '$1\n$2');
  const normalized = content.normalize('NFKD').replace(/[\p{Mn}\p{Cf}]/gu, '');
  return pattern.test(normalized);
}

mobile/src/features/chat/replyRelationsh:
interface ReplyRelationshipInput {
  currentIsMine: boolean;
  quotedIsMine?: boolean;
  quotedAuthor?: string;
  partnerName: string;
}

export function isGenericPhotoReply(text: string, imageUri?: string): boolean {
  if (!imageUri) return false;
  return ['photo', '📷 photo', '🖼 photo', '🖼️ photo'].includes(text.trim().toLocaleLowerCase());
}

export function getReplyRelationship({
  currentIsMine,
  quotedIsMine,
  quotedAuthor = '',
  partnerName,
}: ReplyRelationshipInput): string {
  const name = partnerName.trim() || 'User';
  let originalIsMine = quotedIsMine;

  // Older mobile replies store "You" from the sender's point of view.
  if (originalIsMine === undefined) {
    const author = quotedAuthor.trim().toLocaleLowerCase();
    if (author === 'you') originalIsMine = currentIsMine;
    else if (author === name.toLocaleLowerCase()) originalIsMine = false;
    else originalIsMine = !currentIsMine;
  }

  if (currentIsMine) return originalIsMine ? 'You replied to yourself' : `You replied to ${name}`;
  return originalIsMine ? `${name} replied to you` : `${name} replied to themself`;
}

mobile/src/features/chat/screens/ChatsSc:
import { useLanguage as useUiLanguage } from '../../../shared/localization/LanguageContext';
import React, { useState, useRef, useEffect, useCallback } from 'react';
import { StyleSheet, Text, View, Image, ScrollView, TextInput, Pressable, RefreshControl, Animated } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { useLanguage } from '../../../shared/localization/LanguageContext';
import { useUser } from '../../auth/session/UserContext';
import { resolveRole, type Role } from '../../../app/roleConfig';
import THEME from '../../../shared/theme/theme';
import { AppHeader } from '../../../shared/components/AppHeader';

import { ChatDetailScreen } from '../components/ChatDetailScreen';
import { SupportContactsCard } from '../components/SupportContactsCard';
import { chatStore, ChatConversation, cleanMessagePreview } from '../store/chatStore';
import { useRealtimeStatus } from '../../../shared/realtime/useRealtimeStatus';
import { useChatPresence } from '../../../shared/realtime/useChatPresence';

const serbisureIcon = require('../../../../assets/serbisure-icon.png');

const isOfficialSupportChat = (chat: ChatConversation) => {
  const name = chat.name?.toLowerCase() || '';
  const badge = chat.badge?.toLowerCase() || '';
  const hasCustom = Boolean(
    chat.avatar &&
    !chat.avatar.includes('ui-avatars.com') &&
    !chat.avatar.includes('placeholder') &&
    !chat.avatar.includes('pravatar')
  );
  return (name.includes('support') || name.includes('admin') || badge.includes('support') || badge.includes('admin')) && !hasCustom;
};

export function ChatsScreen({ role: requestedRole, onBookingsPress }: { role?: Role; onBookingsPress?: () => void } = {}) {
  const { tr: uiText } = useUiLanguage();
  const insets = useSafeAreaInsets();
  const { t } = useLanguage();
  const { user } = useUser();
  const liveStatus = useRealtimeStatus();
  const role = requestedRole || resolveRole(user.accountType);

  const [chatList, setChatList] = useState<ChatConversation[]>(chatStore.getChats());
  const [isLoading, setIsLoading] = useState<boolean>(!chatStore.getIsLoaded());
  const [searchQuery, setSearchQuery] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [supportRefresh, setSupportRefresh] = useState(0);
  const [activeChat, setActiveChat] = useState<{
    visible: boolean;
    name: string;
    role: string;
    avatar: string;
    partnerId?: string;
    initialReplyTo?: { author: string; text: string };
  }>({
    visible: false,
    name: '',
    role: '',
    avatar: '',
  });

  const shimmerAnim = useRef(new Animated.Value(0.35)).current;

  useEffect(() => {
    if (isLoading) {
      const pulse = Animated.loop(
        Animated.sequence([
          Animated.timing(shimmerAnim, {
            toValue: 1,
            duration: 800,
            useNativeDriver: true,
          }),
          Animated.timing(shimmerAnim, {
            toValue: 0.35,
            duration: 800,
            useNativeDriver: true,
          }),
        ])
      );
      pulse.start();
      return () => pulse.stop();
    }
  }, [isLoading]);

  const loadInboxData = useCallback(async () => {
    if (user.token) {
      await chatStore.loadInbox(user.token);
      setIsLoading(false);
    } else {
      setIsLoading(false);
    }
  }, [user.token]);

  useEffect(() => {
    setChatList([...chatStore.getChats()]);
    loadInboxData();

    const unsubscribe = chatStore.subscribe(() => {
      setChatList([...chatStore.getChats()]);
      setIsLoading(false);
    });

    return () => {
      unsubscribe();
    };
  }, [loadInboxData]);

  const handleRefresh = async () => {
    setIsRefreshing(true);
    setSupportRefresh(value => value + 1);
    await loadInboxData();
    setIsRefreshing(false);
  };

  const openChat = (
    name: string,
    role: string,
    avatar: string,
    partnerId?: string,
    initialReplyTo?: { author: string; text: string }
  ) => {
    setActiveChat({ visible: true, name, role, avatar, partnerId, initialReplyTo });
  };

  const filteredChats = chatList.filter((c) =>
    c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    c.badge.toLowerCase().includes(searchQuery.toLowerCase()) ||
    c.message.toLowerCase().includes(searchQuery.toLowerCase())
  );
  const presence = useChatPresence(
    user.token ? user.id || user.token : null,
    filteredChats.flatMap(chat => chat.partnerId ? [chat.partnerId] : []),
  );

  return (
    <View style={styles.container}>
      <ScrollView
        style={{ flex: 1, backgroundColor: '#F6F5F2' }}
        contentContainerStyle={[styles.scrollContent, { paddingTop: 8 }]}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl
            refreshing={isRefreshing}
            onRefresh={handleRefresh}
            colors={['#FFB43B']}
            tintColor="#FFB43B"
            progressViewOffset={0}
          />
        }
      >
        {/* Clean Header Area: Title & Pill Search */}
        <View style={styles.headerArea}>
          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: 16 }}>
            <Text style={styles.headerTitle}>{t.chatsHeader || 'Messages'}</Text>
          </View>
          <View style={styles.searchContainer}>
            <Ionicons name="search" size={18} color="#9CA3AF" style={styles.searchIcon} />
            <TextInput
              placeholder={t.searchChats || 'Search messages'}
              placeholderTextColor="#9CA3AF"
              style={styles.searchInput}
              value={searchQuery}
              onChangeText={setSearchQuery}
            />
            {searchQuery.length > 0 && (
              <Pressable onPress={() => setSearchQuery('')} hitSlop={8}>
                <Ionicons name="close-circle" size={18} color="#9CA3AF" />
              </Pressable>
            )}
          </View>
          {(liveStatus === 'unauthorized' || liveStatus === 'reconnecting') && (
            <Text accessibilityLiveRegion="polite" style={styles.connectionNotice}>
              {liveStatus === 'unauthorized' ? uiText("Please sign in again to receive new messages.") : uiText("Reconnecting…")}
            </Text>
          )}
        </View>

        <SupportContactsCard
          key={user.id}
          accountId={user.id || ''}
          token={user.token}
          profileKey={[user.barangay, user.city, user.province].join('|')}
          refreshKey={supportRefresh}
          onContact={contact => openChat(
            contact.account_type === 'Barangay' ? `${contact.barangay} Barangay` : 'SerbiSure Support',
            contact.account_type, contact.avatar || '', contact.id,
          )}
        />

        <Text style={styles.sectionHeader}>{uiText("Recent messages")}</Text>

        <View style={styles.chatList}>
          {isLoading ? (
            <View>
              {[1, 2, 3, 4].map((key) => (
                <Animated.View key={key} style={[styles.skeletonChatCard, { opacity: shimmerAnim }]}>
                  <View style={styles.skeletonAvatar} />
                  <View style={styles.skeletonTextContainer}>
                    <View style={styles.skeletonTopRow}>
                      <View style={styles.skeletonName} />
                      <View style={styles.skeletonTime} />
                    </View>
                    <View style={styles.skeletonSnippet} />
                  </View>
                </Animated.View>
              ))}
            </View>
          ) : filteredChats.length === 0 ? (
            <View style={styles.emptyCard}>
              <View style={styles.emptyIconCircle}>
                <Ionicons name="chatbubbles" size={32} color={THEME.colors.ink} />
              </View>
              <Text style={styles.emptyTitle}>{searchQuery.trim() ? uiText("No messages found") : uiText("No messages yet")}</Text>
              <Text style={styles.emptySub}>
                {searchQuery.trim() ? uiText("Try another name or word.") : uiText("Your conversations will appear here.")}
              </Text>
            </View>
          ) : (
            filteredChats.map((chat) => {
              const hasUnread = (chat.unreadCount || 0) > 0;
              const online = presence(chat.partnerId);
              return (
                <Pressable
                  key={chat.id}
                  style={({ pressed }) => [styles.chatCard, pressed && styles.chatCardPressed]}
                  onPress={() => openChat(chat.name, chat.badge, chat.avatar, chat.partnerId)}
                >
                  <View style={styles.avatarContainer}>
                    <View style={styles.avatarPlaceholder}>
                      <Ionicons name="person" size={22} color="#9CA3AF" />
                    </View>
                    {isOfficialSupportChat(chat) ? (
                      <View style={[styles.avatar, styles.officialAvatarContainer]}>
                        <Image source={serbisureIcon} style={styles.officialAvatarImage} resizeMode="contain" />
                      </View>
                    ) : (
                      <Image source={{ uri: chat.avatar }} style={styles.avatar} fadeDuration={0} />
                    )}
                    {online !== undefined && (
                      <View
                        accessible
                        accessibilityLabel={online ? uiText("Online") : uiText("Offline")}
                        style={[styles.onlineDot, !online && styles.offlineDot]}
                      />
                    )}
                  </View>

                  <View style={styles.chatContent}>
                    <View style={styles.titleRow}>
                      <Text style={[styles.name, hasUnread && styles.nameUnread]} numberOfLines={1}>
                        {chat.name}
                      </Text>
                    </View>

                    <Text
                      style={[styles.message, hasUnread && styles.messageUnread]}
                      numberOfLines={1}
                    >
                      {cleanMessagePreview(chat.message)}
                      {chat.time ? (
                        <Text style={styles.messageTime}>
                          {` · ${uiText(chat.time).replace(' ago', '')}`}
                        </Text>
                      ) : null}
                    </Text>
                  </View>

                  {hasUnread && (
                    <View style={styles.unreadCountBadge}>
                      <Text style={styles.unreadCountBadgeText}>
                        {chat.unreadCount! > 9 ? '9+' : chat.unreadCount}
                      </Text>
                    </View>
                  )}
                </Pressable>
              );
            })
          )}
        </View>

        <View style={{ height: 100 }} />
      </ScrollView>

      {/* Messenger-style Chat Detail Modal */}
      <ChatDetailScreen
        visible={activeChat.visible}
        onClose={() => {
          setActiveChat((prev) => ({ ...prev, visible: false }));
          loadInboxData();
        }}
        partnerId={activeChat.partnerId}
        token={user.token}
        contactName={activeChat.name}
        contactRole={activeChat.role}
        contactAvatar={activeChat.avatar}
        initialReplyTo={activeChat.initialReplyTo}
        userRole={role}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#F6F5F2',
  },
  headerTop: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingHorizontal: 20,
    marginBottom: 16,
    width: '100%',
  },
  headerSide: {
    width: 44,
