import type { ChatMessage } from './components/ChatDetailScreen';

// Session-only history, bounded so long app sessions cannot retain every thread.
const histories = new Map<string, ChatMessage[]>();
const MAX_THREADS = 20;
let generation = 0;

export function threadCacheGeneration(): number { return generation; }

export function getCachedThread(key: string): ChatMessage[] | null {
  const messages = histories.get(key);
  if (!messages) return null;
  histories.delete(key);
  histories.set(key, messages);
  return messages;
}

export function cacheThread(key: string, messages: ChatMessage[], expectedGeneration: number): void {
  if (generation !== expectedGeneration) return;
  const saved = messages.filter(message => !message.id.startsWith('temp-') && !message.isUploading && !message.isTyping);
  histories.delete(key);
  histories.set(key, saved);
  if (histories.size > MAX_THREADS) histories.delete(histories.keys().next().value!);
}

export function forgetCachedThread(key: string): void { histories.delete(key); }

export function clearThreadCache(): void {
  generation++;
  histories.clear();
}

mobile/src/features/chat/threadRefreshQu:
/** Coalesce bursts without losing changes received during a fetch or booking action. */
export function createThreadRefreshQueue(
  load: (initial: boolean) => Promise<unknown>,
  canRun: () => boolean,
) {
  let pending = false;
  let initialPending = false;
  let running = false;
  let stopped = false;

  const drain = async () => {
    if (stopped || running || !pending || !canRun()) return;
    running = true;
    try {
      while (!stopped && pending && canRun()) {
        const initial = initialPending;
        pending = initialPending = false;
        await load(initial);
      }
    } finally {
      running = false;
    }
  };

  return {
    request(initial = false) {
      if (stopped) return;
      pending = true;
      initialPending ||= initial;
      // The screen handles fetch errors. Keep the subscription callback synchronous.
      void drain();
    },
    stop() { stopped = true; pending = initialPending = false; },
  };
}

