import { formatRate } from '../../../shared/utils/rate';
import { useLanguage as useUiLanguage } from '../../../shared/localization/LanguageContext';
import React, { useState, useEffect } from 'react';
import { StyleSheet, Text, View, ScrollView, Pressable, Image, ActivityIndicator } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { RecommendationItem, fetchRecommendations } from '../../bookings/api/bookingApi';

export interface RecommendationsSectionProps {
  token?: string | null;
  accountType?: string;
  onSelectWorker?: (worker: { id: string; name: string; avatar?: string; role: string }) => void;
  onSelectJob?: (job: { id: string; title: string; rate: string }) => void;
}

export function RecommendationsSection({
  token,
  accountType = 'Homeowner',
  onSelectWorker,
  onSelectJob,
}: RecommendationsSectionProps) {
  const { tr: uiText } = useUiLanguage();
  const [items, setItems] = useState<RecommendationItem[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!token) return;
    let isMounted = true;
    setLoading(true);

    fetchRecommendations(token)
      .then((data) => {
        if (isMounted) setItems(data);
      })
      .finally(() => {
        if (isMounted) setLoading(false);
      });

    return () => {
      isMounted = false;
    };
  }, [token]);

  if (!loading && items.length === 0) {
    return null;
  }

  return (
    <View style={styles.container}>
      <View style={styles.headerRow}>
        <View style={styles.titleGroup}>
          <Ionicons name="sparkles" size={17} color="#FFB43B" style={{ marginRight: 6 }} />
          <Text style={styles.title}>
            {uiText(accountType === 'Homeowner' ? 'Top Matched Workers' : 'Recommended Jobs')}
          </Text>
        </View>
        <Text style={styles.subtext}>{uiText("Based on profile information")}</Text>
      </View>

      {loading ? (
        <ActivityIndicator color="#FFB43B" style={{ marginVertical: 20 }} />
      ) : (
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.scrollContent}
        >
          {items.map((item, idx) => {
            const isWorker = accountType === 'Homeowner';
            const nameOrTitle = isWorker ? item.name || 'Kasambahay' : item.title || 'Job';
            const avatarUri =
              (isWorker ? item.avatar : item.poster_avatar) ||
              `https://ui-avatars.com/api/?name=${encodeURIComponent(nameOrTitle)}&background=FFB43B&color=fff`;

            return (
              <Pressable
                key={item.id || item.booking_id || idx}
                style={styles.card}
                onPress={() => {
                  if (isWorker && item.id) {
                    onSelectWorker?.({
                      id: item.id,
                      name: nameOrTitle,
                      avatar: avatarUri,
                      role: item.role || 'Kasambahay',
                    });
                  } else if (!isWorker && item.booking_id) {
                    onSelectJob?.({
                      id: item.booking_id,
                      title: nameOrTitle,
                      rate: item.rate_amount || '',
                    });
                  }
                }}
              >
                {/* Match Score Badge */}
                <View style={styles.matchBadge}>
                  <Text style={styles.matchBadgeText}>{uiText('{count}% Match', { count: item.match_score })}</Text>
                </View>

                {/* Avatar / Icon */}
                <Image source={{ uri: avatarUri }} style={styles.cardAvatar} />

                <Text style={styles.cardName} numberOfLines={1}>
                  {nameOrTitle}
                </Text>

                <Text style={styles.cardLocation} numberOfLines={1}>
                  {item.location}
                </Text>

                {isWorker ? (
                  <View style={styles.metaRow}>
                    <Ionicons name="star" size={12} color="#FFB43B" />
                    <Text style={styles.metaText}>{item.rating && item.rating > 0 ? item.rating.toFixed(1) : uiText('Unrated')}</Text>
                  </View>
                ) : (
                  <View style={styles.metaRow}>
                    <Text style={styles.rateText}>{uiText(formatRate(item.rate_amount))}/{item.rate_period || (item.booking_type === 'long_term' ? 'month' : 'day')}</Text>
                  </View>
                )}
              </Pressable>
            );
          })}
        </ScrollView>
      )}
    </View>
  );
}

