import { useLanguage as useUiLanguage } from '../../../shared/localization/LanguageContext';
import React, { useState, useEffect } from 'react';
import { StyleSheet, Text, View, TextInput, Pressable, Modal, ScrollView, ActivityIndicator, KeyboardAvoidingView, Platform } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

export interface ManageTagsModalProps {
  visible: boolean;
  onClose: () => void;
  currentTags: string[];
  onSave: (newTags: string[]) => Promise<void>;
  accountType?: string;
}

const SUGGESTIONS = [
  'Non-Smoker',
  'Respectful',
  'Pet Owner',
  'Pet Friendly',
  'Family-Oriented',
  'Organized',
  'Punctual',
  'Child Friendly',
  'Trustworthy',
  'Experienced',
  'Reliable',
  'Early Riser',
];

export function ManageTagsModal({
  visible,
  onClose,
  currentTags,
  onSave,
  accountType,
}: ManageTagsModalProps) {
  const { tr: uiText } = useUiLanguage();
  const insets = useSafeAreaInsets();
  const [tags, setTags] = useState<string[]>([]);
  const [inputVal, setInputVal] = useState('');
  const [saving, setSaving] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  useEffect(() => {
    if (visible) {
      setTags([...(currentTags || [])]);
      setInputVal('');
      setErrorMessage(null);
    }
  }, [visible, currentTags]);

  const handleAddTag = (textToAdd?: string) => {
    setErrorMessage(null);
    const rawTag = (textToAdd !== undefined ? textToAdd : inputVal).trim();
    if (!rawTag) return;

    if (tags.length >= 10) {
      setErrorMessage('You can add up to 10 tags only.');
      return;
    }

    if (rawTag.length > 15) {
      setErrorMessage('Each tag must be 15 characters or fewer.');
      return;
    }

    // Case-insensitive duplicate check
    const isDuplicate = tags.some((t) => t.toLowerCase() === rawTag.toLowerCase());
    if (isDuplicate) {
      setErrorMessage(`"${rawTag}" is already added.`);
      return;
    }

    setTags((prev) => [...prev, rawTag]);
    if (textToAdd === undefined) {
      setInputVal('');
    }
  };

  const handleRemoveTag = (indexToRemove: number) => {
    setErrorMessage(null);
    setTags((prev) => prev.filter((_, idx) => idx !== indexToRemove));
  };

  const handleSave = async () => {
    setSaving(true);
    setErrorMessage(null);
    try {
      await onSave(tags);
      onClose();
    } catch (err: any) {
      setErrorMessage(err?.message || 'Failed to save tags. Please try again.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Modal visible={visible} animationType="slide" transparent onRequestClose={onClose}>
      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
        style={styles.modalOverlay}
      >
        <Pressable style={styles.backdrop} onPress={onClose} />

        <View style={[styles.modalSheet, { paddingBottom: Math.max(insets.bottom, 20) }]}>
          {/* Header */}
          <View style={styles.headerRow}>
            <View style={{ flex: 1 }}>
              <Text style={styles.headerTitle}>{uiText("Profile Tags")}</Text>
              <Text style={styles.headerSubtitle}>
                {uiText("Add tags to showcase your lifestyle, preferences, or skills (")}{tags.length}/10)
              </Text>
            </View>
            <Pressable onPress={onClose} style={styles.closeBtn} hitSlop={8}>
              <Ionicons name="close" size={22} color="#666" />
            </Pressable>
          </View>

          <ScrollView
            style={styles.scrollArea}
            contentContainerStyle={styles.scrollContent}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
          >
            {/* Input Row */}
            <View style={styles.inputContainer}>
              <View style={styles.inputWrapper}>
                <Ionicons name="pricetag-outline" size={18} color="#FFB43B" style={{ marginLeft: 12 }} />
                <TextInput
                  style={styles.textInput}
                  placeholder="Type a tag (e.g. Pet Lover)"
                  placeholderTextColor="#9CA3AF"
                  value={inputVal}
                  onChangeText={(val) => {
                    setInputVal(val);
                    if (errorMessage) setErrorMessage(null);
                  }}
                  maxLength={15}
                  returnKeyType="done"
                  onSubmitEditing={() => handleAddTag()}
                />
                <Text style={styles.charCount}>{inputVal.length}/15</Text>
              </View>

              <Pressable
                style={[
                  styles.addBtn,
                  (!inputVal.trim() || tags.length >= 10) && styles.addBtnDisabled,
                ]}
                onPress={() => handleAddTag()}
                disabled={!inputVal.trim() || tags.length >= 10}
              >
                <Ionicons name="add" size={18} color="#FFF" />
                <Text style={styles.addBtnText}>{uiText("Add")}</Text>
              </Pressable>
            </View>

            {/* Error Message */}
            {errorMessage ? (
              <View style={styles.errorBox}>
                <Ionicons name="alert-circle-outline" size={16} color="#DC2626" />
                <Text style={styles.errorText}>{errorMessage}</Text>
              </View>
            ) : null}

            {/* Current Tags */}
            <View style={styles.sectionBlock}>
              <View style={styles.sectionHeadingRow}>
                <Text style={styles.sectionHeading}>{uiText("Your Current Tags")}</Text>
                <Text style={styles.tagCounterText}>{tags.length} {uiText("of 10 max")}</Text>
              </View>

              {tags.length === 0 ? (
                <View style={styles.emptyTagsBox}>
                  <Ionicons name="pricetags-outline" size={28} color="#D1D5DB" />
                  <Text style={styles.emptyTagsText}>{uiText("No tags added yet.")}</Text>
                  <Text style={styles.emptyTagsSub}>
                    {uiText("Create custom tags above or select from quick suggestions below.")}</Text>
                </View>
              ) : (
                <View style={styles.tagsChipContainer}>
                  {tags.map((tag, idx) => (
                    <View key={`${tag}-${idx}`} style={styles.tagChip}>
                      <Text style={styles.tagChipText}>{tag}</Text>
                      <Pressable
                        style={styles.removeTagBtn}
                        onPress={() => handleRemoveTag(idx)}
                        hitSlop={6}
                      >
                        <Ionicons name="close-circle" size={16} color="#B45309" />
                      </Pressable>
                    </View>
                  ))}
                </View>
              )}
            </View>

            {/* Suggested Tags */}
            <View style={styles.sectionBlock}>
              <Text style={styles.sectionHeading}>{uiText("Quick Suggestions")}</Text>
              <Text style={styles.suggestionsSub}>{uiText("Tap to quickly add to your profile:")}</Text>

              <View style={styles.suggestionsContainer}>
                {SUGGESTIONS.map((sug) => {
                  const alreadyAdded = tags.some((t) => t.toLowerCase() === sug.toLowerCase());
                  return (
                    <Pressable
                      key={sug}
                      style={[
                        styles.suggestionPill,
                        alreadyAdded && styles.suggestionPillAdded,
                      ]}
                      onPress={() => {
                        if (alreadyAdded) {
                          const idx = tags.findIndex((t) => t.toLowerCase() === sug.toLowerCase());
                          if (idx !== -1) handleRemoveTag(idx);
                        } else {
                          handleAddTag(sug);
                        }
                      }}
                      disabled={!alreadyAdded && tags.length >= 10}
                    >
                      <Ionicons
                        name={alreadyAdded ? 'checkmark' : 'add'}
                        size={14}
                        color={alreadyAdded ? '#059669' : '#4B5563'}
                        style={{ marginRight: 4 }}
                      />
                      <Text
                        style={[
                          styles.suggestionPillText,
                          alreadyAdded && styles.suggestionPillTextAdded,
                        ]}
                      >
                        {sug}
                      </Text>
                    </Pressable>
                  );
                })}
              </View>
            </View>
          </ScrollView>

          {/* Action Buttons */}
          <View style={styles.actionsFooter}>
            <Pressable style={styles.cancelBtn} onPress={onClose} disabled={saving}>
              <Text style={styles.cancelBtnText}>{uiText("Cancel")}</Text>
            </Pressable>

            <Pressable
              style={[styles.saveBtn, saving && styles.saveBtnDisabled]}
              onPress={handleSave}
              disabled={saving}
            >
              {saving ? (
                <ActivityIndicator size="small" color="#FFF" />
              ) : (
                <>
                  <Ionicons name="checkmark-sharp" size={18} color="#FFF" style={{ marginRight: 6 }} />
                  <Text style={styles.saveBtnText}>{uiText("Save Tags")}</Text>
                </>
              )}
            </Pressable>
          </View>
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

