  authorName?: string;
  authorAvatar?: string;
  authorRole?: string;
  authorLocation?: string;
  children?: React.ReactNode;
}>) {
  const { tr: uiText } = useUiLanguage();
  const { isSaved, toggleSave } = useJobsActivity();

  // If authorName is provided, render the modern feed post card!
  if (authorName || feedPost) {
    const isJob = (authorRole || 'Homeowner') === 'Homeowner';
    const rawCategories = Array.isArray(post.service_category)
      ? post.service_category
      : post.service_category
      ? [post.service_category]
      : [isJob ? 'Household' : 'General Service'];
    const categories = rawCategories.map((value) =>
      !isJob && value === 'Cleaning' ? 'Cleaner' : CATEGORY_LABELS[value] || value.replace(/_/g, ' ')
    );
    const longTerm = post.booking_type === 'long_term';
    const termTag = longTerm ? 'Long-term' : 'Short-term';
    const setupTag = workSetupLabel(post.work_setup);
    const location = formatBookingLocationShort(post, authorLocation || 'Location not provided');
    const numRate = Number(post.rate_amount) || 0;
    const rawPrice = post.rate_amount
      ? `₱ ${numRate.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
      : '₱ 0.00';
    const unit = post.rate_period ? `/${post.rate_period}` : longTerm ? '/month' : '/day';
    const description =
      post.special_instruction?.trim() ||
      (isJob
        ? `I am looking for a ${termTag.toLowerCase()} ${categories.join(' & ')} work in ${location}.`
        : `Available for ${categories.join(' & ')} work in ${location}.`);

    const mappedFeedPost: FeedPost = feedPost || {
      id: post.booking_id,
      start_time: post.start_time, booking_status: post.booking_status, post_status: post.post_status,
      end_time: post.end_time, booking_type: post.booking_type,
      daily_start_time: post.daily_start_time, daily_end_time: post.daily_end_time, work_days: post.work_days,
      partnerId: post.recipient_id || post.booking_id,
      kind: isJob ? 'job' : 'service',
      authorRole: isJob ? 'Homeowner' : 'Kasambahay',
      employerName: authorName || (isJob ? 'Homeowner' : 'Kasambahay'),
      title: categories[0] || (isJob ? 'Household Service' : 'Kasambahay'),
      avatar:
        authorAvatar ||
        `https://ui-avatars.com/api/?name=${encodeURIComponent(authorName || authorRole || 'User')}&background=FFB43B&color=fff`,
      time: formatCompactTimeAgo(post.createdAt),
      location,
      categories,
      roleTag: categories[0] || (isJob ? 'Household Service' : 'Kasambahay'),
      termTag,
      setupTag,
      price: rawPrice,
      unit,
      aboutText: description,
      tags: Array.from(new Set([termTag, setupTag, ...categories])),
    };

    const isPostSaved = saved !== undefined ? saved : isSaved(post.booking_id);

    return (
      <FeedPostCard
        post={mappedFeedPost}
        saved={isPostSaved}
        onToggleSave={onToggleSave || (() => { void toggleSave(mappedFeedPost, token); })}
        onDetails={() => onDetails?.(mappedFeedPost)}
        leftActionButton={children}
      />
    );
  }

  // Fallback for PendingPostsSection in user's own profile screen
  return (
    <View style={styles.pendingPostCard}>
      <View style={styles.pendingPostTopRow}>
        <View style={styles.categoryChipsWrap}>
          {post.service_category.map((category, index) => (
            <View key={`${category}-${index}`} style={styles.categoryChip}>
              <Text style={styles.categoryChipText}>{category.replace(/_/g, ' ')}</Text>
            </View>
          ))}
        </View>
        <View style={styles.pendingStatusBadge}>
          <Ionicons name="time" size={11} color="#B45309" style={{ marginRight: 3 }} />
          <Text style={styles.pendingStatusBadgeText}>{uiText("Pending")}</Text>
        </View>
      </View>
      <View style={styles.pendingPostRateRow}>
        <Text style={styles.pendingPostRate}>{uiText(formatRate(post.rate_amount))}</Text>
        <Text style={styles.pendingPostRateUnit}>
          {' '}
          {post.rate_needs_review ? '(unit needs confirmation)' : '/ ' + post.rate_period} ·{' '}
          {post.booking_type === 'long_term' ? uiText("Long-term") : uiText("Short-term")}
        </Text>
      </View>
      <Text style={styles.pendingPostDetailText}>
        {uiText("Work setup:")} {workSetupLabel(post.work_setup)}
      </Text>
      <View style={styles.pendingPostDetails}>
        <View style={styles.pendingPostDetailItem}>
          <Ionicons name="location-outline" size={13} color="#6B7280" style={{ marginRight: 4 }} />
          <Text style={styles.pendingPostDetailText} numberOfLines={2}>
            {formatBookingAddress(post)}
          </Text>
        </View>
      </View>
      {post.special_instruction ? (
        <View style={styles.pendingPostInstructionBox}>
          <Text style={styles.pendingPostInstructionText}>{post.special_instruction}</Text>
        </View>
      ) : null}
      <View style={styles.pendingPostProposalsRow}>
        <Ionicons name="people-outline" size={13} color="#D97706" style={{ marginRight: 5 }} />
        <Text style={styles.pendingPostProposalsText}>{note}</Text>
      </View>
      {children ? <View style={styles.pendingPostActionsRow}>{children}</View> : null}
    </View>
  );
}

import { useLanguage as useUiLanguage } from '../../../shared/localization/LanguageContext';
import React from 'react';
import { Text, View, Pressable, ActivityIndicator } from 'react-native';

import { Ionicons } from '@expo/vector-icons';

import { PendingPostCard } from './PendingPostCard';
import { CancelBookingModal } from '../../bookings/components/CancelBookingModal';

import { profileStyles as styles } from '../styles';
import type { ProfileController } from '../hooks/useProfile';

export function PendingPostsSection({ profile }: { profile: ProfileController }) {
  const { tr: uiText } = useUiLanguage();
  const [cancelTarget, setCancelTarget] = React.useState<string | null>(null);
  const {
    copy,
    pendingPosts,
    isLoadingPendingPosts,
    pendingPostsError,
    openMyBookings,
    loadPendingPosts,
  } = profile;
  return (<>
    <View style={styles.pendingPostsSection}>
      <View style={styles.tabSectionHeader}>
        <View style={{ flex: 1, marginRight: 8 }}>
          <Text style={styles.tabSectionTitle}>{uiText("My Pending Posts")}</Text>
          <Text style={styles.tabSectionSubtitle}>
            {copy.pendingPosts}
          </Text>
        </View>
        <Pressable
          style={styles.refreshIconBtn}
          onPress={() => loadPendingPosts(false)}
          disabled={isLoadingPendingPosts}
          hitSlop={8}
        >
          <Ionicons
            name="refresh-outline"
            size={15}
            color={isLoadingPendingPosts ? '#9CA3AF' : '#EA580C'}
          />
        </Pressable>
      </View>

      {/* State 1: Loading */}
      {isLoadingPendingPosts ? (
        <View style={styles.postsLoadingTile}>
          <ActivityIndicator size="small" color="#FFB380" />
          <Text style={styles.postsLoadingText}>{uiText("Loading your pending posts...")}</Text>
        </View>
      ) : pendingPostsError ? (
        /* State 2: Error */
        <View style={styles.postsErrorTile}>
          <Ionicons name="alert-circle-outline" size={32} color="#DC2626" />
          <Text style={styles.postsErrorTitle}>{uiText("Failed to load pending posts")}</Text>
          <Text style={styles.postsErrorSubtitle}>{pendingPostsError}</Text>
          <Pressable style={styles.postsRetryButton} onPress={() => loadPendingPosts(false)}>
            <Ionicons name="reload" size={13} color="#FFFFFF" style={{ marginRight: 4 }} />
            <Text style={styles.postsRetryButtonText}>{uiText("Try Again")}</Text>
          </Pressable>
        </View>
      ) : pendingPosts.length === 0 ? (
        /* State 3: Empty */
        <View style={styles.emptyPendingPostsCard}>
          <View style={styles.emptyPostsIconCircle}>
            <Ionicons name="time-outline" size={26} color="#9CA3AF" />
          </View>
          <Text style={styles.emptyPendingPostsTitle}>{uiText("No Pending Posts")}</Text>
          <Text style={styles.emptyPendingPostsSubtitle}>
            {copy.emptyPosts}
          </Text>
        </View>
      ) : (
        /* State 4: Success / List */
        <View style={styles.pendingPostsList}>
          {pendingPosts.map((post) => {
            const isCancelling = cancelTarget === post.booking_id;
            return (
              <PendingPostCard key={post.booking_id} post={post} note={post.proposals_count && post.proposals_count > 0 ? `${post.proposals_count} Proposal(s) received` : copy.waiting}>
                {/* Action Buttons */}
                  <Pressable
                    style={styles.pendingPostManageBtn}
                    onPress={() => openMyBookings('pending')}
                  >
                    <Ionicons name="options-outline" size={14} color="#0D0D11" style={{ marginRight: 4 }} />
                    <Text style={styles.pendingPostManageBtnText}>{uiText("Manage Post")}</Text>
                  </Pressable>

                  <Pressable
                    style={[styles.pendingPostCancelBtn, isCancelling && { opacity: 0.6 }]}
                    onPress={() => setCancelTarget(post.booking_id)}
                    disabled={isCancelling}
                  >
                    {isCancelling ? (
                      <ActivityIndicator size="small" color="#DC2626" />
                    ) : (
                      <>
                        <Ionicons name="close-circle-outline" size={14} color="#DC2626" style={{ marginRight: 3 }} />
                        <Text style={styles.pendingPostCancelBtnText}>{uiText("Cancel")}</Text>
                      </>
                    )}
                  </Pressable>
              </PendingPostCard>
            );
          })}
        </View>
      )}
    </View>
    {cancelTarget && profile.user.token && <CancelBookingModal key={cancelTarget} bookingId={cancelTarget} token={profile.user.token}
      onClose={() => setCancelTarget(null)} onCancelled={safety => {
        setCancelTarget(null);
        if (safety) profile.returnToDashboard();
        else void loadPendingPosts(true);
      }} />}
  </>);
}

import { useLanguage as useUiLanguage } from '../../../shared/localization/LanguageContext';
import React, { useRef, useState, useEffect } from 'react';
import {
  StyleSheet,
  Text,
  View,
  Modal,
  Pressable,
  ScrollView,
  Linking,
  NativeSyntheticEvent,
  NativeScrollEvent,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import THEME from '../../../shared/theme/theme';

interface PrivacyPolicyModalProps {
  visible: boolean;
  onClose: () => void;
  document?: 'privacy' | 'terms';
  onAccept?: () => void;
  onDecline?: () => void;
  mode?: 'consent' | 'view';
}

export function PrivacyPolicyModal({
  visible,
  onClose,
  document = 'privacy',
  onAccept,
  onDecline,
  mode,
}: PrivacyPolicyModalProps) {
  const insets = useSafeAreaInsets();
  const { tr: uiText } = useUiLanguage();
  const isTerms = document === 'terms';
  const isConsentMode = mode ? mode === 'consent' : Boolean(onAccept);
  const scrollViewRef = useRef<ScrollView>(null);
  const [hasScrolledToBottom, setHasScrolledToBottom] = useState(false);

  useEffect(() => {
    if (visible) {
      setHasScrolledToBottom(false);
    }
  }, [visible]);

  const handleOpenEmail = () => {
    Linking.openURL('mailto:privacy@serbisure.ph?subject=Privacy Inquiry').catch(() => {});
  };

  const handleScroll = (event: NativeSyntheticEvent<NativeScrollEvent>) => {
    const { layoutMeasurement, contentOffset, contentSize } = event.nativeEvent;
    const paddingToBottom = 40;
    if (layoutMeasurement.height + contentOffset.y >= contentSize.height - paddingToBottom) {
      setHasScrolledToBottom(true);
    }
  };

  const handleAccept = () => {
    if (!hasScrolledToBottom) {
      if (typeof scrollViewRef.current?.scrollToEnd === 'function') {
        scrollViewRef.current.scrollToEnd({ animated: true });
      } else {
        scrollViewRef.current?.scrollTo?.({ y: 99999, animated: true });
      }
      setHasScrolledToBottom(true);
    } else {
      if (onAccept) {
        onAccept();
      } else {
        onClose();
      }
    }
  };

  const handleDecline = () => {
    if (onDecline) {
      onDecline();
    } else {
      onClose();
    }
  };

  return (
    <Modal
      visible={visible}
      animationType="slide"
      onRequestClose={onClose}
    >
      <View style={[styles.fullScreenContainer, { paddingTop: Math.max(insets.top, 20) }]}>
        <ScrollView
          ref={scrollViewRef}
          onScroll={handleScroll}
          scrollEventThrottle={16}
          showsVerticalScrollIndicator={false}
          contentContainerStyle={styles.scrollContent}
        >
          {/* Header */}
          <Text style={styles.agreementTag}>{uiText("AGREEMENT")}</Text>
          <Text style={styles.modalTitle}>
            {uiText(isTerms ? "Terms of Service" : "Privacy Policy")}
          </Text>

          {isTerms ? <TermsContent /> : <PrivacyContent handleOpenEmail={handleOpenEmail} />}
        </ScrollView>

        {/* Bottom Actions: Decline & Accept (consent mode) OR Back & Understood (settings view) */}
        <View style={[styles.bottomBar, { paddingBottom: Math.max(insets.bottom, 16) }]}>
          <Pressable
            style={({ pressed }) => [styles.declineBtn, pressed && styles.btnPressed]}
            onPress={isConsentMode ? handleDecline : onClose}
          >
            <Text style={styles.declineBtnText}>{uiText(isConsentMode ? "Decline" : "Back")}</Text>
          </Pressable>
          <Pressable
            style={({ pressed }) => [styles.acceptBtn, pressed && styles.btnPressed]}
            onPress={isConsentMode ? handleAccept : onClose}
          >
            <Text style={styles.acceptBtnText}>{uiText(isConsentMode ? "Accept" : "Understood")}</Text>
          </Pressable>
        </View>
      </View>
    </Modal>
  );
}

