// Product thresholds for a lightweight challenge followed by manual review.
// They are not a certified presentation-attack detection policy.
export const LIVENESS = {
  landmarkTurn: 0.025,
  yawTurnDegrees: 4,
  calibrationMs: 200,
  calibrationFrames: 3,
  turnHoldMs: 400,
  turnFrames: 3,
  maxFrameGapMs: 1000,
  interruptionGraceMs: 600,
  maxObservedIntervalMs: 250,
  stillnessMs: 1000,
  movementTolerance: 0.22,
  inferenceFps: 8,
  // Photo framing is independent of the deliberately sensitive turn checks.
  photoCenterTolerance: 0.30,
  photoMaxFaceSize: 0.96,
  photoLandmarkTolerance: 0.08,
  photoYawToleranceDegrees: 12,
  // At least three observations still span the 1 s photo hold at low FPS.
  photoMaxObservedIntervalMs: 500,
} as const;

import { getFaceAlignment, getHeadPoseDirection, getHeadPoseSample, getPhotoReadiness, getStillnessProgress, type HeadPoseSample } from './livenessRules';
import { LIVENESS } from './livenessConfig';
import type { FaceLandmarks, LandmarkFrame } from '../face/types';

export type LivenessStep = 'face' | 'turnLeft' | 'turnRight' | 'still' | 'verified';

export type LivenessResult = {
  verified: true;
  completedAt: number;
  selfiePath: string;
};

export type LivenessState = {
  step: LivenessStep;
  completedSteps: LivenessStep[];
  instruction: string;
  verified: boolean;
  retryMessage: string | null;
  stillnessProgress: number;
  stillnessPausedAt: number | null;
  stableFace: FaceLandmarks | null;
  stepStartedAt: number | null;
  actionSince: number | null;
  lastFrameAt: number | null;
  neutralPose: HeadPoseSample | null;
  neutralSamples: number[];
  actionFrames: number;
  actionProgressMs: number;
  actionPausedAt: number | null;
};

export const initialLivenessState: LivenessState = {
  step: 'face',
  completedSteps: [],
  instruction: 'Look at the camera for a moment',
  verified: false,
  retryMessage: null,
  stillnessProgress: 0,
  stillnessPausedAt: null,
  stableFace: null,
  stepStartedAt: null,
  actionSince: null,
  lastFrameAt: null,
  neutralPose: null,
  neutralSamples: [],
  actionFrames: 0,
  actionProgressMs: 0,
  actionPausedAt: null,
};

const stepInstructions: Record<LivenessStep, string> = {
  face: 'Look at the camera for a moment',
  turnRight: 'Slowly turn your head a little to your right',
  turnLeft: 'Great! Now turn a little to your left',
  still: 'Well done! Look at the camera for your photo',
  verified: 'Face verification complete',
};

function completeStep(state: LivenessState, completed: LivenessStep, next: LivenessStep, now: number): LivenessState {
  return {
    ...state,
    step: next,
    completedSteps: state.completedSteps.includes(completed)
      ? state.completedSteps
      : [...state.completedSteps, completed],
    instruction: stepInstructions[next],
    retryMessage: null,
    stillnessProgress: 0,
    stillnessPausedAt: null,
    stableFace: null,
    actionSince: null,
    actionFrames: 0,
    actionProgressMs: 0,
    actionPausedAt: null,
    stepStartedAt: now,
  };
}

export function retryCurrentStep(state: LivenessState): LivenessState {
  return {
    ...state,
    retryMessage: null,
    stillnessProgress: 0,
    stillnessPausedAt: null,
    stableFace: null,
    actionSince: null,
    actionFrames: 0,
    actionProgressMs: 0,
    actionPausedAt: null,
    neutralPose: state.step === 'face' ? null : state.neutralPose,
    neutralSamples: state.step === 'face' ? [] : state.neutralSamples,
    stepStartedAt: null,
    lastFrameAt: null,
  };
}

function resetTurn(state: LivenessState): LivenessState {
  return { ...state, actionSince: null, actionFrames: 0, actionProgressMs: 0, actionPausedAt: null };
}

function pauseTurn(state: LivenessState, now: number, previousAt: number | null): LivenessState {
  if (state.actionSince === null) return state;
  const pausedAt = state.actionPausedAt ?? previousAt ?? now;
  return now - pausedAt > LIVENESS.interruptionGraceMs
    ? resetTurn(state) : { ...state, actionPausedAt: pausedAt };
}

export function prepareSelfieRetake(state: LivenessState): LivenessState {
  if (!state.verified) return state;
  return {
    ...retryCurrentStep(state),
    verified: false,
    step: 'still',
    instruction: stepInstructions.still,
    completedSteps: state.completedSteps.filter(step => step !== 'still'),
  };
}

export function advanceLiveness(state: LivenessState, frame: LandmarkFrame): LivenessState {
  if (state.verified) {
    return state;
  }

  // Stale/out-of-order frames cannot complete a challenge. A paused detector
  // must observe the current action again instead of counting the pause.
  if (state.lastFrameAt !== null && frame.timestamp <= state.lastFrameAt) return state;
  const previousFrameAt = state.lastFrameAt;
  if (state.step !== 'still' && previousFrameAt !== null && frame.timestamp - previousFrameAt > LIVENESS.maxFrameGapMs) {
    state = resetTurn(state);
    if (state.step === 'face') state = { ...state, neutralPose: null, neutralSamples: [], stepStartedAt: null };
  }
  state = { ...state, lastFrameAt: frame.timestamp, stepStartedAt: state.stepStartedAt ?? frame.timestamp };
  const isTurningStep = state.step === 'turnRight' || state.step === 'turnLeft';
  const alignment = getFaceAlignment(frame, isTurningStep);
  const face = frame.face;

  if (state.step === 'still') {
    const { ready, instruction } = getPhotoReadiness(frame, state.neutralPose);
    const stillness = getStillnessProgress(ready ? face : null, {
      stableFace: state.stableFace,
      progress: state.stillnessProgress,
      pausedAt: state.stillnessPausedAt,
    }, frame.timestamp, previousFrameAt);
    return {
      ...state,
      step: stillness.isStill ? 'verified' : 'still',
      completedSteps: stillness.isStill ? [...state.completedSteps, 'still'] : state.completedSteps,
      instruction: stillness.isStill ? stepInstructions.verified : instruction,
      verified: stillness.isStill,
      retryMessage: null,
      stillnessProgress: stillness.isStill ? 1 : stillness.progress,
      stillnessPausedAt: stillness.pausedAt,
      stableFace: stillness.stableFace,
    };
  }

  if (!face || !alignment.centered) {
    state = pauseTurn(state, frame.timestamp, previousFrameAt);
    return {
      ...state,
      instruction: face ? 'Gently move your face into the circle' : 'Bring your face back into the circle when you are ready',
      retryMessage: null,
      stillnessProgress: 0,
      stillnessPausedAt: null,
      stableFace: null,
      ...(state.step === 'face' ? { neutralPose: null, neutralSamples: [], stepStartedAt: frame.timestamp } : {}),
    };
  }

  if (state.step === 'face') {
    const pose = getHeadPoseSample(face);
    if (!pose) return { ...state, neutralPose: null, neutralSamples: [], stepStartedAt: frame.timestamp };
    const samples = [...state.neutralSamples, pose.offset].slice(-5);
    if (state.neutralPose && (state.neutralPose.source !== pose.source || Math.max(...samples) - Math.min(...samples) > pose.threshold * 2)) {
      return { ...state, neutralPose: pose, neutralSamples: [pose.offset], stepStartedAt: frame.timestamp };
    }
    const sorted = [...samples].sort((a, b) => a - b);
    state = { ...state, neutralSamples: samples, neutralPose: { ...pose, offset: sorted[Math.floor(sorted.length / 2)]! }, instruction: stepInstructions.face };
    if (samples.length < LIVENESS.calibrationFrames || frame.timestamp - state.stepStartedAt! < LIVENESS.calibrationMs) return state;
    return completeStep(state, 'face', 'turnRight', frame.timestamp);
  }

  const headPose = getHeadPoseDirection(face, state.neutralPose);

  if (state.step === 'turnRight' || state.step === 'turnLeft') {
    const expected = state.step === 'turnRight' ? 'right' : 'left';
    if (headPose !== expected) {
      state = headPose === 'center' || headPose === 'unknown'
        ? pauseTurn(state, frame.timestamp, previousFrameAt) : resetTurn(state);
      return { ...state, instruction: stepInstructions[state.step], retryMessage: null };
    }
    if (state.actionPausedAt !== null && frame.timestamp - state.actionPausedAt > LIVENESS.interruptionGraceMs) state = resetTurn(state);
    const observedInterval = state.actionSince !== null && state.actionPausedAt === null && previousFrameAt !== null
      ? Math.min(frame.timestamp - previousFrameAt, LIVENESS.maxObservedIntervalMs) : 0;
    const actionSince = state.actionSince ?? frame.timestamp;
    const actionFrames = state.actionFrames + 1;
    const actionProgressMs = state.actionProgressMs + observedInterval;
    if (actionFrames >= LIVENESS.turnFrames && actionProgressMs >= LIVENESS.turnHoldMs) {
      return completeStep(state, state.step, state.step === 'turnRight' ? 'turnLeft' : 'still', frame.timestamp);
    }
    return { ...state, actionSince, actionFrames, actionProgressMs, actionPausedAt: null, instruction: stepInstructions[state.step], retryMessage: null };
  }

  return state;
}

import { FACE_LANDMARKS } from '../face/landmarkIndexes';
import { landmark } from '../face/geometry';
import { LIVENESS } from './livenessConfig';
import type { FaceAlignment, FaceLandmarks, HeadPoseDirection, LandmarkFrame } from '../face/types';

const CENTER_TOLERANCE = 0.22;
const TURNING_CENTER_TOLERANCE = 0.32;
const MIN_FACE_SIZE = 0.18;
const MAX_FACE_SIZE = 0.82;

export function getFaceAlignment(frame: LandmarkFrame, isTurning = false): FaceAlignment {
  return getAlignment(frame, isTurning ? TURNING_CENTER_TOLERANCE : CENTER_TOLERANCE, MAX_FACE_SIZE);
}

function getAlignment(frame: LandmarkFrame, tolerance: number, maxFaceSize: number): FaceAlignment {
  if (!frame.face) {
    return {
      centered: false,
      visible: false,
      faceCenterX: 0,
      faceCenterY: 0,
      faceSizeRatio: 0,
    };
  }

  const { bounds } = frame.face;
  const faceCenterX = (bounds.x + bounds.width / 2) / frame.frameWidth;
  const faceCenterY = (bounds.y + bounds.height / 2) / frame.frameHeight;
  const faceSizeRatio = Math.max(bounds.width / frame.frameWidth, bounds.height / frame.frameHeight);
  const centered =
    Math.abs(faceCenterX - 0.5) <= tolerance &&
    Math.abs(faceCenterY - 0.5) <= tolerance &&
    faceSizeRatio >= MIN_FACE_SIZE &&
    faceSizeRatio <= maxFaceSize;

  return {
    centered,
    visible: true,
    faceCenterX,
    faceCenterY,
    faceSizeRatio,
  };
}

export type HeadPoseSample = { source: 'landmarks' | 'yaw'; offset: number; threshold: number };

export function getHeadPoseSample(face: FaceLandmarks): HeadPoseSample | null {
  const nose = landmark(face, FACE_LANDMARKS.noseTip);
  const leftCheek = landmark(face, FACE_LANDMARKS.leftCheek);
  const rightCheek = landmark(face, FACE_LANDMARKS.rightCheek);
  if (face.points.length > 0) {
    if (!nose || !leftCheek || !rightCheek) return null;
    const yScale = face.signals?.landmarkYScale ?? 1;
    if (!Number.isFinite(yScale) || yScale <= 0) return null;
    const dx = rightCheek.x - leftCheek.x;
    const dy = (rightCheek.y - leftCheek.y) * yScale;
    const spanSquared = dx * dx + dy * dy;
    if (!Number.isFinite(spanSquared) || spanSquared < 1) return null;
    // Both vectors follow image rotation/mirroring. Positive means the
    // applicant's right, matching pose-only detectors' yaw convention.
    const offset = -(
      (nose.x - (leftCheek.x + rightCheek.x) / 2) * dx +
      (nose.y - (leftCheek.y + rightCheek.y) / 2) * yScale * dy
    ) / spanSquared;
    return Number.isFinite(offset) ? { source: 'landmarks', offset, threshold: LIVENESS.landmarkTurn } : null;
  }
  const yaw = face.signals?.yawAngle;
  return typeof yaw === 'number' && Number.isFinite(yaw)
    ? { source: 'yaw', offset: yaw, threshold: LIVENESS.yawTurnDegrees } : null;
}

export function getHeadPoseDirection(face: FaceLandmarks, neutral: HeadPoseSample | null = null): HeadPoseDirection {
  const pose = getHeadPoseSample(face);
  if (!pose || (neutral && pose.source !== neutral.source)) return 'unknown';
  const offset = pose.offset - (neutral?.offset ?? 0);
  if (offset > pose.threshold) return 'right';
  if (offset < -pose.threshold) return 'left';
  return 'center';
}

export function getPhotoReadiness(frame: LandmarkFrame, neutral: HeadPoseSample | null) {
  const face = frame.face;
  if (!face) return { ready: false, instruction: 'Look at the camera so we can see your face.' };
  const alignment = getAlignment(frame, LIVENESS.photoCenterTolerance, LIVENESS.photoMaxFaceSize);
  const { bounds } = face;
  const fitsFrame = frame.frameWidth > 0 && frame.frameHeight > 0 &&
    bounds.x >= -frame.frameWidth * 0.05 && bounds.y >= -frame.frameHeight * 0.05 &&
    bounds.x + bounds.width <= frame.frameWidth * 1.05 &&
    bounds.y + bounds.height <= frame.frameHeight * 1.05;
  if (alignment.faceSizeRatio > LIVENESS.photoMaxFaceSize || !fitsFrame) {
    return { ready: false, instruction: 'Move your phone a little farther away so your face fits.' };
  }
  if (!alignment.centered) return { ready: false, instruction: 'Gently bring your face into the circle.' };
  const pose = getHeadPoseSample(face);
  const tolerance = pose?.source === 'yaw' ? LIVENESS.photoYawToleranceDegrees : LIVENESS.photoLandmarkTolerance;
  const facingCamera = pose && (!neutral || pose.source === neutral.source) &&
    Math.abs(pose.offset - (neutral?.offset ?? 0)) <= tolerance;
  return facingCamera
    ? { ready: true, instruction: 'Well done! Look at the camera for your photo' }
    : { ready: false, instruction: 'Look straight at the camera. A relaxed position is fine.' };
}

export function getHeadPoseDetails(face: FaceLandmarks | null): {
  direction: HeadPoseDirection;
  offset: number;
} {
  if (!face) return { direction: 'unknown', offset: 0 };
  return {
    direction: getHeadPoseDirection(face),
    offset: getHeadPoseSample(face)?.offset ?? 0,
  };
}

export function getStillnessProgress(
  current: FaceLandmarks | null,
  previous: { stableFace: FaceLandmarks | null; progress: number; pausedAt: number | null },
  now: number,
  lastFrameAt: number | null,
) {
  const before = previous.stableFace?.bounds;
  const bounds = current?.bounds;
  const scale = bounds ? Math.max(bounds.width, bounds.height, 1) : 1;
  const moved = before && bounds && Math.max(
    Math.abs(bounds.x - before.x), Math.abs(bounds.y - before.y),
    Math.abs(bounds.width - before.width), Math.abs(bounds.height - before.height),
  ) / scale > LIVENESS.movementTolerance;
  const delta = lastFrameAt === null ? 0 : Math.max(0, now - lastFrameAt);
  if (current && delta > LIVENESS.maxFrameGapMs) {
    // A fresh usable frame after startup/tracking loss is the new reference.
    // Do not count the outage, or make it wait an extra frame unlike a retake.
    return { isStill: false, progress: 0, pausedAt: null, stableFace: current };
  }
  if (!current || moved) {
    const pausedAt = previous.pausedAt ?? lastFrameAt ?? now;
    const expired = now - pausedAt > LIVENESS.interruptionGraceMs;
    return {
      isStill: false,
      progress: expired ? 0 : previous.progress,
      pausedAt,
      stableFace: expired ? null : previous.stableFace,
    };
  }

  const expired = previous.pausedAt !== null && now - previous.pausedAt > LIVENESS.interruptionGraceMs;
  // Only observed steady intervals count. Brief interruptions preserve progress
  // without counting missing frames or the time spent moving.
  const increment = previous.stableFace && previous.pausedAt === null
    ? Math.min(delta, LIVENESS.photoMaxObservedIntervalMs) / LIVENESS.stillnessMs : 0;
  const progress = expired ? 0 : Math.min(previous.progress + increment, 1);

  return {
    isStill: progress >= 1 - Number.EPSILON,
    progress,
    pausedAt: null,
    stableFace: current,
  };
}

