import { useLanguage as useUiLanguage } from '../localization/LanguageContext';
import React, { useState, useMemo } from 'react';
import {
  Modal,
  View,
  Text,
  TextInput,
  Pressable,
  FlatList,
  StyleSheet,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import THEME from '../theme/theme';

export interface DemographicOption {
  id: string;
  label: string;
  sublabel?: string;
  badge?: string;
}

interface DemographicPickerModalProps {
  visible: boolean;
  title: string;
  subtitle?: string;
  options: DemographicOption[];
  selectedValue?: string | null;
  searchPlaceholder?: string;
  allowCustomInput?: boolean;
  onSelect: (val: string) => void;
  onClose: () => void;
}

export function DemographicPickerModal({
  visible,
  title,
  subtitle,
  options,
  selectedValue,
  searchPlaceholder = 'Search...',
  allowCustomInput = false,
  onSelect,
  onClose,
}: DemographicPickerModalProps) {
  const { tr: uiText } = useUiLanguage();
  const [searchQuery, setSearchQuery] = useState('');
  const [customValue, setCustomValue] = useState('');
  const [isTypingCustom, setIsTypingCustom] = useState(false);

  const filteredOptions = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return options;
    return options.filter(
      (opt) =>
        opt.label.toLowerCase().includes(q) ||
        (opt.sublabel && opt.sublabel.toLowerCase().includes(q))
    );
  }, [options, searchQuery]);

  const handleSelect = (id: string) => {
    if (id === 'OTHER_CUSTOM' && allowCustomInput) {
      setIsTypingCustom(true);
      return;
    }
    onSelect(id);
    onClose();
    setSearchQuery('');
    setIsTypingCustom(false);
  };

  const handleConfirmCustom = () => {
    if (customValue.trim()) {
      onSelect(customValue.trim());
      setCustomValue('');
      setIsTypingCustom(false);
      onClose();
    }
  };

  return (
    <Modal
      visible={visible}
      animationType="slide"
      presentationStyle="pageSheet"
      onRequestClose={onClose}
    >
      <SafeAreaView style={styles.container} edges={['top', 'bottom']}>
        {/* Header */}
        <View style={styles.header}>
          <View style={{ flex: 1 }}>
            <Text style={styles.headerTitle}>{title}</Text>
            {subtitle ? <Text style={styles.headerSubtitle}>{subtitle}</Text> : null}
          </View>
          <Pressable onPress={onClose} style={styles.closeBtn} hitSlop={10}>
            <Ionicons name="close" size={22} color="#4A4945" />
          </Pressable>
        </View>

        {/* Search Bar */}
        <View style={styles.searchContainer}>
          <Ionicons name="search" size={18} color="#9CA3AF" style={styles.searchIcon} />
          <TextInput
            style={styles.searchInput}
            placeholder={searchPlaceholder}
            placeholderTextColor="#9CA3AF"
            value={searchQuery}
            onChangeText={setSearchQuery}
            autoCapitalize="words"
          />
          {searchQuery.length > 0 && (
            <Pressable onPress={() => setSearchQuery('')} hitSlop={8}>
              <Ionicons name="close-circle" size={18} color="#9CA3AF" />
            </Pressable>
          )}
        </View>

        {/* Custom input drawer if "Other" was clicked */}
        {isTypingCustom ? (
          <View style={styles.customInputCard}>
            <Text style={styles.customInputLabel}>{uiText("Please specify:")}</Text>
            <View style={styles.customInputRow}>
              <TextInput
                style={styles.customInput}
                placeholder="Enter custom value..."
                placeholderTextColor="#9CA3AF"
                value={customValue}
                onChangeText={setCustomValue}
                autoFocus
              />
              <Pressable
                style={[styles.customConfirmBtn, !customValue.trim() && { opacity: 0.5 }]}
                disabled={!customValue.trim()}
                onPress={handleConfirmCustom}
              >
                <Text style={styles.customConfirmBtnText}>{uiText("Save")}</Text>
              </Pressable>
            </View>
          </View>
        ) : null}

        {/* Options List */}
        <FlatList
          data={filteredOptions}
          keyExtractor={(item) => item.id}
          contentContainerStyle={styles.listContent}
          showsVerticalScrollIndicator={false}
          renderItem={({ item }) => {
            const isSelected = item.id === selectedValue || item.label === selectedValue;
            return (
              <Pressable
                style={({ pressed }) => [
                  styles.optionRow,
                  isSelected && styles.optionRowSelected,
                  pressed && styles.optionRowPressed,
                ]}
                onPress={() => handleSelect(item.id)}
              >
                <View style={styles.optionLeft}>
                  <Text
                    style={[styles.optionLabel, isSelected && styles.optionLabelSelected]}
                    numberOfLines={1}
                  >
                    {uiText(item.label)}
                  </Text>
                  {item.sublabel ? (
                    <Text style={styles.optionSublabel} numberOfLines={1}>
