    backgroundColor: '#FFFFFF',
    borderWidth: 1.5,
    borderColor: '#FFCCAA',
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'hidden',
  },
  initials: { color: THEME.colors.brandDark, fontFamily: THEME.typography.fontFamily.display },
});

