  );
  return res.data ?? res.results ?? [];
}

/**
 * Send a text message to a user as the admin.
 * POST /api/v1/chat/send/
 * Requires Idempotency-Key header (fresh UUID v4 per call).
 */
export async function sendChatMessage(
  receiverId: string,
  messagePayload: string,
  languageWarningAcknowledged = false,
): Promise<ChatMessage> {
  const idempotencyKey = createRequestId();
  const res = await fetchApi<{ message: string; data: ChatMessage; language_warning?: string | null }>(
    '/api/v1/chat/send/',
    {
      method: 'POST',
      headers: { 'Idempotency-Key': idempotencyKey },
      body: JSON.stringify({ receiver_id: receiverId, message_payload: messagePayload, ...(languageWarningAcknowledged ? { language_warning_acknowledged: true } : {}) }),
    }
  );
  return { ...res.data, language_warning: res.language_warning };
}

/**
 * Send an image message with optional caption to a user as the admin.
 * POST /api/v1/chat/send-image/
 * Supports JPEG, PNG, and WEBP up to 10MB.
 * Requires Idempotency-Key header.
 * Uses FormData so apiClient lets the browser set multipart boundary.
 */
export async function sendChatImageMessage(
  receiverId: string,
  imageFile: File,
  caption?: string,
  languageWarningAcknowledged = false,
): Promise<ChatMessage> {
  const idempotencyKey = createRequestId();
  const formData = new FormData();
  formData.append('language_warning_acknowledged', String(languageWarningAcknowledged));
  formData.append('receiver_id', receiverId);
  formData.append('image', imageFile);
  if (caption && caption.trim()) {
    formData.append('message_payload', caption.trim());
  }

  const res = await fetchApi<{ message: string; data: ChatMessage; language_warning?: string | null }>(
    '/api/v1/chat/send-image/',
    {
      method: 'POST',
      headers: { 'Idempotency-Key': idempotencyKey },
      body: formData,
    }
  );
  return { ...res.data, language_warning: res.language_warning };
}

