          </td>
          <td>
            <div style="font-weight: 700; color: #1E293B;">${escapeHtml(timeDisplay)}</div>
            ${logSub ? `<div class="sub-text" style="font-family: monospace; font-size: 10px; color: #94A3B8;">${escapeHtml(logSub)}</div>` : ''}
          </td>
        </tr>
      `;
    }).join('');
  }

  const classification = meta.searchTerm 
    ? `Filtered by "${meta.searchTerm}"` 
    : 'All Recorded Entries (Unfiltered)';

  return `
  <div class="report-wrapper" style="box-sizing: border-box; width: 1400px; background: #FFFFFF; padding: 48px 56px 72px 56px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; color: #0F172A; line-height: 1.5; overflow: hidden;">
    <style>
      .report-wrapper * { box-sizing: border-box; }
      .brand-badge {
        display: inline-block;
        font-size: 11px;
        font-weight: 800;
        color: #475569;
        letter-spacing: 0.8px;
        text-transform: uppercase;
        margin-bottom: 8px;
        white-space: nowrap;
      }
      .report-title {
        font-size: 26px;
        font-weight: 900;
        color: #0F172A;
        letter-spacing: -0.5px;
        margin: 0 0 6px 0;
      }
      .report-subtitle {
        font-size: 12.5px;
        font-weight: 500;
        color: #64748B;
        margin: 0;
      }
      .logo-title {
        font-size: 24px;
        font-weight: 900;
        letter-spacing: -0.5px;
        color: #0F172A;
      }
      .logo-orange {
        color: #FF7A00;
      }
      .logo-sub {
        font-size: 10px;
        font-weight: 700;
        color: #94A3B8;
        letter-spacing: 0.5px;
        text-transform: uppercase;
        margin-top: 2px;
      }
      .meta-grid {
        width: 100%;
        table-layout: fixed;
        margin-top: 24px;
        margin-bottom: 28px;
        border-collapse: separate;
        border-spacing: 12px 0;
      }
      .meta-card {
        background: #F8FAFC;
        border: 1px solid #E2E8F0;
        border-radius: 10px;
        padding: 12px 16px;
        vertical-align: top;
      }
      .meta-card-label {
        font-size: 10px;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.7px;
        color: #94A3B8;
        margin-bottom: 4px;
      }
      .meta-card-val {
        font-size: 13px;
        font-weight: 800;
        color: #0F172A;
      }
      table.data-table {
        width: 100%;
        table-layout: fixed;
        border-collapse: separate;
        border-spacing: 0;
        background: #FFFFFF;
        border: 1px solid #E2E8F0;
        border-radius: 12px;
