import React from 'react';
import { 
  LayoutDashboard, 
  CheckCircle2, 
  Users,
  ShieldCheck,
  Scale,
  Settings, 
  LogOut,
  PanelLeft,
  PanelRight,
  X
} from 'lucide-react';
import { useAdmin } from '../../context/AdminContext';
import { groupVerificationApplicants } from '../../data/verificationApplicants';

interface SidebarProps {
  isSidebarCollapsed: boolean;
  setIsSidebarCollapsed: (v: boolean) => void;
  isMobileMenuOpen?: boolean;
  setIsMobileMenuOpen?: (v: boolean) => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  isSidebarCollapsed, 
  setIsSidebarCollapsed,
  isMobileMenuOpen = false,
  setIsMobileMenuOpen
}) => {
  const { currentRole, selectedBarangay, activeNav, setActiveNav, verifications, currentUser, logout, unreadChatCount } = useAdmin();

  const pendingCount = groupVerificationApplicants(verifications).filter(applicant => applicant.status === 'PENDING / REVIEW').length;

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'verifications', label: 'Verifications', icon: CheckCircle2, badge: pendingCount },
    { id: 'users', label: 'Users', icon: Users, badge: unreadChatCount },
    { id: 'account-access', label: 'Account Access', icon: ShieldCheck },
    { id: 'penalty-points', label: 'Penalty Points', icon: Scale },
    { id: 'settings', label: 'Settings', icon: Settings },
  ];

  const handleNavClick = (id: string) => {
    setActiveNav(id);
    if (setIsMobileMenuOpen) {
      setIsMobileMenuOpen(false);
    }
  };

  return (
    <aside 
      className={`bg-white flex flex-col justify-between gap-6 select-none shrink-0 overflow-y-auto overscroll-contain overflow-x-hidden transition-all duration-300 ease-in-out fixed inset-y-0 left-0 z-50 w-72 max-w-[calc(100vw-3rem)] lg:max-w-none h-dvh shadow-2xl lg:shadow-none lg:static lg:sticky lg:top-0 lg:z-40 p-5 lg:p-6 ${
        isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
      } ${
        isSidebarCollapsed ? 'lg:w-16 lg:px-2.5 lg:py-5 lg:items-center' : 'lg:w-64 lg:p-6'
      }`}
    >
      {/* Top Section */}
      <div className="flex flex-col gap-6 w-full">

        {/* Toggle Button & Brand Header */}
        <div className="w-full">
