        <td className={cell}><p className="text-xs text-zinc-600">{penaltyDate(record.created_at)}</p><p className="mt-1 text-xs text-zinc-500">Period: {record.penalty_month.slice(0, 7)}</p></td>
      </tr>)}</tbody>
    </table>
  </div>;
}

