interface Props { accountId: string | undefined; role: string; barangay: string; revision: number }

export function AccountAccessHistory({ accountId, role, barangay, revision }: Props): React.ReactElement {
  const [search, setSearch] = useState('');
  const [filters, setFilters] = useState<{ search: string; action: AccessAction | ''; page: number }>({ search: '', action: '', page: 1 });
  const [exportMessage, setExportMessage] = useState<string | null>(null);
  const [isExporting, setIsExporting] = useState(false);
  const exportRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const timer = setTimeout(() => setFilters(value => value.search === search.trim() ? value : { ...value, search: search.trim(), page: 1 }), 300);
    return () => clearTimeout(timer);
  }, [search]);
  const history = useAccessHistory(accountId, role, barangay, filters, revision);
  const pages = Math.max(1, Math.ceil((history.data?.count || 0) / PAGE_SIZE));
  const rows = history.data?.results || [];
  const handleExport = async () => {
    if (isExporting) return;
    setIsExporting(true);
    setExportMessage(null);
    try {
      if (!accountId || !exportRef.current) throw new Error('Export is unavailable. Please try again.');
      const entries = await fetchAllAccessHistory({ search: filters.search, action: filters.action, barangay });
      if (!entries.length) {
        setExportMessage('No data to export for the current filters.');
        return;
      }
      exportRef.current.innerHTML = accessHistoryExportMarkup(entries, barangay);
      const canvas = await html2canvas(exportRef.current, {
        scale: 2,
        useCORS: true,
        logging: false,
        backgroundColor: '#FFFFFF',
        windowWidth: 1400,
        scrollX: 0,
        scrollY: 0,
      });
      const orientation = canvas.width >= canvas.height ? 'landscape' : 'portrait';
      const pdf = new jsPDF({ orientation, unit: 'px', format: [canvas.width, canvas.height] });
      pdf.addImage(canvas.toDataURL('image/png'), 'PNG', 0, 0, canvas.width, canvas.height);
      pdf.save(`serbisure-access-history-${new Date().toISOString().slice(0, 10)}.pdf`);
      setExportMessage('Access history downloaded successfully.');
    } catch {
      setExportMessage('Export failed. Please try again.');
    } finally {
      if (exportRef.current) exportRef.current.innerHTML = '';
      setIsExporting(false);
      window.setTimeout(() => setExportMessage(null), 4000);
    }
  };
  return <div className="min-w-0 space-y-5 sm:space-y-6" aria-label="Account access history">
    <div className="grid grid-cols-[minmax(0,1fr)_auto] gap-2.5 sm:gap-4 sm:grid-cols-[minmax(0,1fr)_auto_auto]">
      <label className="relative min-w-0 col-span-2 sm:col-span-1"><span className="sr-only">Search history by user, official or barangay</span><Search aria-hidden="true" size={18} className="pointer-events-none absolute left-4 top-3.5 text-zinc-400" /><input maxLength={200} className={`${field} pl-12 sm:pl-12`} value={search} onChange={event => setSearch(event.target.value)} placeholder="Search user, official or barangay" /></label>
      <label className="relative"><span className="sr-only">Filter history by action</span><select className={`${field} appearance-none pr-12`} value={filters.action} onChange={event => setFilters(value => ({ ...value, action: event.target.value as AccessAction | '', page: 1 }))}>
        <option value="">All changes</option>{(Object.entries(accessActionLabels) as [AccessAction, string][]).map(([action, label]) => <option key={action} value={action}>{label}</option>)}
      </select><ChevronDown aria-hidden="true" size={18} className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-zinc-500" /></label>
      <button type="button" onClick={handleExport} disabled={isExporting} className={`${secondary} inline-flex items-center justify-center gap-2 whitespace-nowrap`} aria-label="Export access history">
        {isExporting ? <Loader2 size={16} className="animate-spin" /> : <Download size={16} />}
        {isExporting ? 'Exporting…' : 'Export'}
      </button>
    </div>
    {exportMessage && <div role="status" className={`flex items-center gap-2 rounded-xl border px-4 py-2 text-xs font-medium ${exportMessage.startsWith('Export failed') || exportMessage.startsWith('No data') ? 'border-amber-200/60 bg-amber-50 text-amber-800' : 'border-emerald-200/60 bg-emerald-50 text-emerald-700'}`}>
      {exportMessage.startsWith('Export failed') || exportMessage.startsWith('No data') ? <AlertCircle size={16} /> : <CheckCircle2 size={16} />}
      <span>{exportMessage}</span>
    </div>}
    <div className="overflow-hidden rounded-2xl sm:rounded-3xl bg-white" aria-busy={history.loading}>
      {history.error && <div role="alert" className="flex flex-wrap items-center justify-between gap-4 p-6"><p className="text-sm text-red-700">{history.error}</p><button type="button" className={secondary} onClick={history.refresh}>Retry</button></div>}
      {!history.data && !history.error && <p role="status" className="p-6 text-sm text-zinc-500">Loading access history…</p>}
      {history.data && !rows.length && <div className="space-y-2 p-6"><h2 className="font-semibold">{filters.search || filters.action ? 'No matching changes' : 'No access changes yet'}</h2><p className="text-sm text-zinc-500">{filters.search || filters.action ? 'Try another search or select all changes.' : 'Suspensions and restorations will appear here.'}</p></div>}
      {rows.length > 0 && <>
        <AccessHistoryTable entries={rows} />
        <footer className="flex flex-wrap items-center justify-between gap-4 px-6 py-5">
          <p className="text-xs text-zinc-500">Showing {(filters.page - 1) * PAGE_SIZE + 1}–{(filters.page - 1) * PAGE_SIZE + rows.length} of {history.data?.count} changes</p>
          {pages > 1 && <nav aria-label="Access history pages" className="flex items-center gap-3"><button type="button" className={secondary} disabled={history.loading || filters.page <= 1} onClick={() => setFilters(value => ({ ...value, page: value.page - 1 }))} aria-label="Previous history page"><ChevronLeft size={16} /></button><span className="text-xs text-zinc-500">{filters.page} / {pages}</span><button type="button" className={secondary} disabled={history.loading || filters.page >= pages} onClick={() => setFilters(value => ({ ...value, page: value.page + 1 }))} aria-label="Next history page"><ChevronRight size={16} /></button></nav>}
        </footer>
      </>}
    </div>
    <div ref={exportRef} aria-hidden="true" style={{ position: 'absolute', left: '-10000px', top: 0, width: '1400px', pointerEvents: 'none', background: '#FFFFFF' }} />
  </div>;
}

import React, { useState } from 'react';
import { AccountControls } from './AccountControls';
import { accountAccessStatus, type AccountAccessUser, type AccessStatus } from '../../data/accountAccess';

const statusStyle: Record<AccessStatus, string> = {
  available: 'bg-emerald-50 text-emerald-700', chat_paused: 'bg-amber-50 text-amber-800',
  account_suspended: 'bg-rose-50 text-rose-700', deactivated: 'bg-zinc-100 text-zinc-600',
};
const statusLabel: Record<AccessStatus, string> = {
  available: 'Available', chat_paused: 'Messaging paused', account_suspended: 'Account suspended', deactivated: 'Deactivated',
};

function Avatar({ user }: { user: AccountAccessUser }): React.ReactElement {
  const [failed, setFailed] = useState(false);
  const initials = user.name.trim().split(/\s+/).slice(0, 2).map(part => part[0]).join('');
  return <div className="flex h-9 w-9 shrink-0 items-center justify-center overflow-hidden rounded-full bg-[#F6F5F2] text-xs font-bold text-zinc-600">
    {user.avatar && !failed ? <img src={user.avatar} alt="" className="h-full w-full object-cover" onError={() => setFailed(true)} /> : initials}
  </div>;
}

interface Props { users: AccountAccessUser[]; now: number; onSaved: (name: string) => void; disabled?: boolean }

export function AccountAccessTable({ users, now, onSaved, disabled = false }: Props): React.ReactElement {
  return <div className="overflow-x-hidden md:overflow-x-auto">
    <table className="block w-full text-left text-sm md:table md:table-fixed">
      <caption className="sr-only">Homeowner and Kasambahay account access</caption>
      <thead className="hidden text-xs text-zinc-500 md:table-header-group">
        <tr className="contents md:table-row">
          <th scope="col" className="block px-5 py-3 font-semibold md:table-cell md:w-[42%] md:px-6 xl:w-[32%]">User</th>
          <th scope="col" className="hidden w-[23%] px-6 py-3 font-semibold xl:table-cell">Barangay</th>
          <th scope="col" className="block px-3 py-3 font-semibold md:table-cell md:px-6">Access</th>
          <th scope="col" className="hidden w-28 px-3 py-3 text-right font-semibold md:table-cell md:w-48 md:px-6 xl:w-52"><span className="sr-only">Actions</span></th>
        </tr>
      </thead>
      <tbody className="block divide-y divide-zinc-100 md:table-row-group">
        {users.map(user => {
          const status = accountAccessStatus(user, now);
          const barangay = (user.barangay || '').replace(/^(brgy\.?|barangay)\s+/i, '').trim() || 'Unassigned';
          return <tr key={user.id} className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-x-3 gap-y-3 p-4 align-middle md:table-row md:p-0">
            <td className="col-span-2 block px-0 py-0 md:table-cell md:px-6 md:py-4">
              <div className="flex items-center gap-3">
                <Avatar key={user.avatar} user={user} />
                <div className="min-w-0">
                  <p className="[overflow-wrap:anywhere] text-sm font-bold text-[#0D0D11]">{user.name}</p>
                  <div className="mt-1 flex flex-wrap gap-x-2 gap-y-0.5 text-[11px] sm:text-xs text-zinc-500 md:block">
                    <p>{user.role === 'HOMEOWNER' ? 'Homeowner' : 'Kasambahay'}</p>
                    <p className="break-words md:mt-1 xl:hidden">{barangay === 'Unassigned' ? barangay : `Brgy. ${barangay}`}</p>
                  </div>
                </div>
              </div>
            </td>
            <td className="hidden break-words px-6 py-4 text-zinc-500 xl:table-cell">{barangay === 'Unassigned' ? barangay : `Brgy. ${barangay}`}</td>
            <td className="block min-w-0 px-0 py-0 md:table-cell md:px-6 md:py-4">
              <span className="sr-only">Access: </span>
              <span className={`inline-block rounded-full px-2.5 py-1.5 text-[11px] sm:text-xs font-semibold ${statusStyle[status]}`}>{statusLabel[status]}</span>
              {status === 'chat_paused' && user.chatSuspendedUntil && <p className="mt-1 text-xs leading-4 text-zinc-500">Until {new Date(user.chatSuspendedUntil).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })}</p>}
            </td>
            <td className="col-span-1 flex items-end justify-end px-0 py-0 text-right md:table-cell md:px-6 md:py-4">
              {user.canManageSuspension ? <AccountControls userId={user.id} name={user.name} disabled={disabled} onSaved={() => onSaved(user.name)} /> : <span className="text-xs text-zinc-500">Not permitted</span>}
            </td>
          </tr>;
        })}
      </tbody>
    </table>
  </div>;
}

