import React, { useState } from 'react';
import { FileText, Loader2 } from 'lucide-react';
import type { VerificationRequest } from '../../types/admin';
import { getOptimizedWebpUrl } from '../../utils/imageOptimizer';
import { VerificationStatusBadge } from './VerificationStatusBadge';

interface Props {
  document: VerificationRequest;
  selected: boolean;
  onReview: () => void;
  onApprove: (id: string) => Promise<void>;
  onReject: (id: string, reason?: string) => Promise<void>;
  onReset: (id: string) => Promise<void>;
}

export const VerificationDocumentRow: React.FC<Props> = ({ document, selected, onReview, onApprove, onReject, onReset }) => {
  const [rejecting, setRejecting] = useState(false);
  const [reason, setReason] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const decide = async (action: 'approve' | 'reject' | 'reset') => {
    if (busy) return;
    setBusy(true); setError(null);
    try {
      if (action === 'approve') await onApprove(document.id);
      else if (action === 'reset') await onReset(document.id);
      else await onReject(document.id, reason.trim() || 'Document criteria not met');
      setRejecting(false); setReason('');
    } catch (error) {
      setError(error instanceof Error ? error.message : 'Could not save this review. Please try again.');
    } finally { setBusy(false); }
  };
  return (
    <div className={`verification-document-card rounded-xl border p-3 ${selected ? 'border-orange-200 bg-orange-50/40' : 'border-zinc-200/70 bg-white'}`}>
      <div className="flex flex-wrap items-center gap-3">
        <button type="button" onClick={onReview} aria-label={`Review ${document.documentType}`} className="flex min-w-0 flex-1 items-center gap-3 text-left cursor-pointer rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-200">
          <span className="flex h-12 w-10 shrink-0 items-center justify-center overflow-hidden rounded-lg bg-zinc-100">
            {document.documentImage ? <img src={getOptimizedWebpUrl(document.documentImage, { width: 80, height: 96, quality: 'auto' })} alt="" loading="lazy" className="h-full w-full object-cover" /> : <FileText className="h-5 w-5 text-zinc-400" />}
          </span>
          <span className="min-w-0">
            <span className="block text-xs font-semibold text-zinc-900">{document.documentType}</span>
            <span className="mt-1 block text-[11px] text-zinc-500">{document.submittedDate}</span>
          </span>
        </button>
        <VerificationStatusBadge status={document.isExpired && document.status !== 'REJECTED' ? 'EXPIRED' : document.status} />
        <div className="verification-document-actions flex flex-wrap items-center gap-2" aria-busy={busy}>
          <button type="button" onClick={onReview} className="px-2 py-2 text-xs font-semibold text-zinc-600 hover:text-zinc-950 cursor-pointer">Review</button>
          {document.status === 'VERIFIED' ? (
            <button type="button" disabled={busy} onClick={() => void decide('reset')} className="rounded-full bg-zinc-100 px-3 py-2 text-xs font-semibold text-zinc-700 disabled:opacity-50 cursor-pointer">Re-open</button>
          ) : (
            <>
              {document.status !== 'REJECTED' && <button type="button" disabled={busy} onClick={() => { setRejecting(value => !value); setError(null); }} className="rounded-full bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-700 disabled:opacity-50 cursor-pointer">Reject</button>}
              <button type="button" disabled={busy} onClick={() => void decide('approve')} className="inline-flex items-center gap-1.5 rounded-full bg-emerald-600 px-3 py-2 text-xs font-semibold text-white disabled:opacity-50 cursor-pointer">
                {busy && <Loader2 className="h-3 w-3 animate-spin" />} Approve
              </button>
            </>
          )}
        </div>
      </div>
      {document.isExpired && <p className="mt-2 text-xs text-orange-800">Expired on {document.validityDate}. {document.status === 'REJECTED' ? 'Renewal requested.' : 'Process expirations to request a renewed clearance.'}</p>}
      {document.status === 'REJECTED' && document.notes && <p className="mt-2 text-xs text-rose-700 break-words">{document.notes}</p>}
      {rejecting && (
        <form className="mt-3 flex flex-wrap items-center gap-2" onSubmit={event => { event.preventDefault(); void decide('reject'); }}>
          <input aria-label={`Rejection reason for ${document.documentType}`} placeholder="Reason for rejection (optional)" value={reason} onChange={event => setReason(event.target.value)} disabled={busy} className="min-w-0 flex-1 rounded-xl border border-zinc-200 px-3 py-2 text-xs focus:outline-none focus:ring-2 focus:ring-orange-200" />
          <button type="button" onClick={() => setRejecting(false)} disabled={busy} className="px-2 py-2 text-xs text-zinc-500 cursor-pointer">Cancel</button>
          <button type="submit" disabled={busy} className="rounded-full bg-rose-600 px-3 py-2 text-xs font-semibold text-white disabled:opacity-50 cursor-pointer">Confirm rejection</button>
        </form>
      )}
      {error && <p role="alert" className="mt-2 text-xs text-rose-700">{error}</p>}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ChevronDown, ChevronLeft, ChevronRight, FileText, RotateCw, Clock, CheckCircle, XCircle, FileQuestion } from 'lucide-react';
import { useAdmin } from '../../context/AdminContext';
import { AccountRole } from '../../types/admin';
import { getOptimizedWebpUrl } from '../../utils/imageOptimizer';
import { groupVerificationApplicants, preferredDocument } from '../../data/verificationApplicants';
import { VerificationStatusBadge } from './VerificationStatusBadge';
import { VerificationDocumentRow } from './VerificationDocumentRow';
import { ProcessExpirationsButton } from './ProcessExpirationsButton';

type StatusFilter = 'PENDING' | 'VERIFIED' | 'REJECTED' | 'EXPIRED' | 'NO_DOCUMENTS' | 'ALL';

export const VerificationQueue: React.FC = () => {
  const { 
    verifications, 
    selectedVerificationId, 
    setSelectedVerificationId,
    openComparisonModal,
    isComparisonModalOpen,
    approveVerification,
    rejectVerification,
    resetVerification,
    isLoadingVerifications,
    refreshVerifications,
    refreshUsers,
    refreshDashboardStats,
    refreshMonthlyTrend,
    refreshAuditLogs,
    currentRole,
    selectedBarangay,
    userBarangays,
  } = useAdmin();

  const [statusFilter, setStatusFilter] = useState<StatusFilter>('PENDING');
  const [roleFilter, setRoleFilter] = useState<'ALL' | AccountRole>('ALL');
  const [barangayFilter, setBarangayFilter] = useState<string>('ALL');
  const [sortOrder, setSortOrder] = useState<'RECENT' | 'OLDEST'>('RECENT');
  const [expandedApplicantId, setExpandedApplicantId] = useState<string | null>(null);

  // Helper to normalize barangay strings
  const cleanBarangayName = (name?: string) => {
    return (name || '').replace(/^(brgy\.?|barangay)\s+/i, '').trim();
  };

  // Dynamically compute all distinct barangays across registered residents and queue verifications
  const allBarangayOptions = React.useMemo(() => {
    const map = new Map<string, string>();
    (userBarangays || []).forEach((b) => {
      const cleaned = cleanBarangayName(b);
      if (cleaned && cleaned.toLowerCase() !== 'all' && cleaned.toLowerCase() !== 'all barangays' && cleaned.toLowerCase() !== 'unassigned') {
        const key = cleaned.toLowerCase();
        if (!map.has(key)) {
          const formatted = cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
          map.set(key, formatted);
        }
      }
    });

    verifications.forEach((v) => {
      const cleaned = cleanBarangayName(v.barangay);
      if (cleaned && cleaned.toLowerCase() !== 'all' && cleaned.toLowerCase() !== 'all barangays' && cleaned.toLowerCase() !== 'unassigned') {
        const key = cleaned.toLowerCase();
        if (!map.has(key)) {
          const formatted = cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
          map.set(key, formatted);
        }
      }
    });

    return Array.from(map.values()).sort((a, b) => a.localeCompare(b));
  }, [userBarangays, verifications]);

  const hasUnassigned = React.useMemo(() => {
    return verifications.some(
      v => v.hasLguCoverage === false || !v.barangay || cleanBarangayName(v.barangay).toLowerCase() === 'unassigned'
    );
  }, [verifications]);

  // Strictly scope queue to assigned barangay if logged in as local LGU officer or unassigned perspective
  const scopedVerifications = (currentRole === 'ADMIN' && selectedBarangay)
    ? verifications.filter(v => cleanBarangayName(v.barangay).toLowerCase() === cleanBarangayName(selectedBarangay).toLowerCase())
    : (selectedBarangay === 'UNASSIGNED'
        ? verifications.filter(v => v.hasLguCoverage === false || (v.barangay || '').toLowerCase() === 'unassigned')
        : verifications);

  // Barangay filter strictly for Superadmin (specific LGU admins are already scoped to their assigned LGU)
  const barangayScopedVerifications = (currentRole === 'SUPERADMIN' && barangayFilter !== 'ALL')
    ? scopedVerifications.filter(v => {
        if (barangayFilter === 'UNASSIGNED') {
          return v.hasLguCoverage === false || !v.barangay || cleanBarangayName(v.barangay).toLowerCase() === 'unassigned';
        }
        return cleanBarangayName(v.barangay).toLowerCase() === cleanBarangayName(barangayFilter).toLowerCase();
      })
    : scopedVerifications;

  const applicants = groupVerificationApplicants(barangayScopedVerifications)
    .filter(applicant => roleFilter === 'ALL' || applicant.user.role === roleFilter);
  const pendingCount = applicants.filter(v => v.status === 'PENDING / REVIEW').length;
  const verifiedCount = applicants.filter(v => v.status === 'VERIFIED').length;
  const rejectedCount = applicants.filter(v => v.status === 'REJECTED').length;
  const expiredCount = applicants.filter(v => v.status === 'EXPIRED').length;
  const noDocumentsCount = applicants.filter(v => v.status === 'NO_DOCUMENTS').length;
  const totalCount = applicants.length;

  const filteredVerifications = applicants
    .filter(v => {
      // Status filter
      if (statusFilter === 'PENDING' && v.status !== 'PENDING / REVIEW') return false;
      if (statusFilter === 'VERIFIED' && v.status !== 'VERIFIED') return false;
      if (statusFilter === 'REJECTED' && v.status !== 'REJECTED') return false;
      if (statusFilter === 'EXPIRED' && v.status !== 'EXPIRED') return false;
      if (statusFilter === 'NO_DOCUMENTS' && v.status !== 'NO_DOCUMENTS') return false;

      return true;
    })
    .sort((a, b) => {
      const dateA = a.submittedAt;
      const dateB = b.submittedAt;
      return sortOrder === 'RECENT' ? dateB - dateA : dateA - dateB;
    });

  // Pagination State (10 items per page)
  const ITEMS_PER_PAGE = 5;
  const [currentPage, setCurrentPage] = useState<number>(1);

  // Total filtered records
  const totalRecords = filteredVerifications.length;
  const totalPages = Math.max(1, Math.ceil(totalRecords / ITEMS_PER_PAGE));

  // Reset pagination to page 1 whenever any filter or sorting criteria changes
  useEffect(() => {
    setCurrentPage(1);
    setExpandedApplicantId(null);
  }, [statusFilter, roleFilter, barangayFilter, sortOrder, selectedBarangay]);

  // Idiot-proof clamp: If currentPage is somehow greater than totalPages, clamp safely
  useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(totalPages);
    }
  }, [currentPage, totalPages]);

  // Sliced paginated records for the current page
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const endIndex = Math.min(startIndex + ITEMS_PER_PAGE, totalRecords);
  const paginatedVerifications = filteredVerifications.slice(startIndex, endIndex);

  // Auto-select first item on the current page if current selection is not visible on this page
  useEffect(() => {
    if (isComparisonModalOpen) return;
    if (paginatedVerifications.length > 0) {
      const isVisibleOnPage = paginatedVerifications.some(applicant =>
        applicant.user.id === selectedVerificationId || applicant.documents.some(document => document.id === selectedVerificationId));
      if (!isVisibleOnPage) {
        setSelectedVerificationId(preferredDocument(paginatedVerifications[0]).id);
      }
    } else if (selectedVerificationId) {
      setSelectedVerificationId('');
    }
  }, [paginatedVerifications, selectedVerificationId, setSelectedVerificationId, isComparisonModalOpen]);

  // Generate page numbers with ellipsis for large page counts
  const getPageNumbers = () => {
    const pages: (number | string)[] = [];
    if (totalPages <= 5) {
      for (let i = 1; i <= totalPages; i++) {
        pages.push(i);
      }
    } else {
      if (currentPage <= 3) {
        pages.push(1, 2, 3, 4, '...', totalPages);
      } else if (currentPage >= totalPages - 2) {
        pages.push(1, '...', totalPages - 3, totalPages - 2, totalPages - 1, totalPages);
      } else {
        pages.push(1, '...', currentPage - 1, currentPage, currentPage + 1, '...', totalPages);
      }
    }
    return pages;
  };

  return (
    <div className="verification-queue min-w-0 bg-white rounded-2xl sm:rounded-3xl p-4 sm:p-6 lg:p-7 h-full flex flex-col">
      {/* Header with Filters */}
      <div className="flex flex-col items-start pb-5 gap-3.5">
        <div>
          <h3 className="text-xl font-black font-display text-[#0D0D11] tracking-tight">
            <span className="sm:hidden">Applicants</span><span className="hidden sm:inline">Verification Queue</span>
          </h3>
          <p className="text-xs text-zinc-400 mt-0.5 font-medium">
            {currentRole === 'SUPERADMIN' && barangayFilter !== 'ALL' && (
              <span className="text-zinc-700 font-bold mr-1">
                [{barangayFilter === 'UNASSIGNED' ? 'Unassigned' : `Brgy. ${barangayFilter}`}]
              </span>
            )}
            {statusFilter === 'PENDING' 
              ? `${pendingCount} applicant${pendingCount === 1 ? '' : 's'} awaiting review`
              : statusFilter === 'NO_DOCUMENTS'
              ? `${noDocumentsCount} user${noDocumentsCount === 1 ? '' : 's'} without documents`
              : `${filteredVerifications.length} applicant${filteredVerifications.length === 1 ? '' : 's'} listed`}
          </p>
        </div>

        {/* Filters wrap within the panel so every control is reachable on phones. */}
        <div className="verification-queue-filters grid grid-cols-[minmax(0,1fr)_minmax(0,1fr)_40px] sm:flex sm:flex-wrap items-center gap-2 w-full py-0.5">
          {/* Barangay Filter Dropdown - SUPERADMIN ONLY */}
          {currentRole === 'SUPERADMIN' && (
            <div className="relative min-w-0 col-span-3 sm:flex-1">
              <select
                value={barangayFilter}
                aria-label="Filter applicants by barangay"
                onChange={(e) => setBarangayFilter(e.target.value)}
                className="appearance-none bg-[#F0F0EC] hover:bg-[#EBEBE6] text-zinc-800 text-xs font-bold py-2 pl-3.5 pr-8 rounded-full cursor-pointer focus:outline-none focus:ring-2 focus:ring-[#FFB380]/40 border-0 transition-colors"
                title="Filter residents by Barangay"
              >
                <option value="ALL">All Barangays</option>
                {allBarangayOptions.map((bgy) => (
                  <option key={bgy} value={bgy}>
                    Brgy. {bgy}
                  </option>
                ))}
                {hasUnassigned && (
                  <option value="UNASSIGNED">Unassigned / No LGU</option>
                )}
              </select>
              <ChevronDown className="w-3.5 h-3.5 text-zinc-600 absolute right-2.5 top-1/2 -translate-y-1/2 pointer-events-none" />
            </div>
          )}

          {/* Role Filter Dropdown */}
          <div className="relative min-w-0 sm:flex-1">
            <select
              value={roleFilter}
              aria-label="Filter applicants by role"
              onChange={(e) => setRoleFilter(e.target.value as any)}
              className="appearance-none bg-[#F0F0EC] hover:bg-[#EBEBE6] text-zinc-800 text-xs font-bold py-2 pl-3.5 pr-8 rounded-full cursor-pointer focus:outline-none focus:ring-2 focus:ring-[#FFB380]/40 border-0 transition-colors"
            >
              <option value="ALL">All Roles</option>
              <option value="KASAMBAHAY">Kasambahay</option>
              <option value="HOMEOWNER">Homeowner</option>
            </select>
            <ChevronDown className="w-3.5 h-3.5 text-zinc-600 absolute right-2.5 top-1/2 -translate-y-1/2 pointer-events-none" />
          </div>

          {/* Sort Order Dropdown */}
          <div className="relative min-w-0 sm:flex-1">
            <select
              value={sortOrder}
              aria-label="Sort applicants"
              onChange={(e) => setSortOrder(e.target.value as any)}
              className="appearance-none bg-[#F0F0EC] hover:bg-[#EBEBE6] text-zinc-800 text-xs font-bold py-2 pl-3.5 pr-8 rounded-full cursor-pointer focus:outline-none focus:ring-2 focus:ring-[#FFB380]/40 border-0 transition-colors"
            >
              <option value="RECENT">Recent First</option>
              <option value="OLDEST">Oldest First</option>
            </select>
            <ChevronDown className="w-3.5 h-3.5 text-zinc-600 absolute right-2.5 top-1/2 -translate-y-1/2 pointer-events-none" />
          </div>

          {/* Live Sync Refresh Button - Sleek, integrated, always beside Recent First filter */}
          <button
            type="button"
            onClick={() => refreshVerifications()}
            title="Sync with Backend"
            className="w-10 h-10 rounded-full bg-[#F0F0EC] text-zinc-700 hover:bg-[#E5E5E0] hover:text-zinc-900 transition-all flex items-center justify-center shrink-0 cursor-pointer border-0 active:scale-95"
            aria-label="Refresh Queue"
          >
            <RotateCw className={`w-3.5 h-3.5 ${isLoadingVerifications ? 'animate-spin' : ''}`} />
          </button>
        </div>
      </div>

      <ProcessExpirationsButton onProcessed={async () => {
        await Promise.all([refreshVerifications(), refreshUsers(), refreshDashboardStats(), refreshMonthlyTrend(), refreshAuditLogs()]);
        window.dispatchEvent(new Event('serbisure:verification_changed'));
      }} />

      {/* Status Filter Tabs - Unified Pill Badges */}
      <div className="grid grid-cols-3 sm:flex sm:flex-wrap items-center gap-1.5 sm:gap-2 pb-4">
        {[
          { id: 'PENDING', label: 'Pending', icon: Clock, count: pendingCount },
          { id: 'VERIFIED', label: 'Verified', icon: CheckCircle, count: verifiedCount },
          { id: 'REJECTED', label: 'Rejected', icon: XCircle, count: rejectedCount },
          { id: 'EXPIRED', label: 'Expired', icon: Clock, count: expiredCount },
          { id: 'NO_DOCUMENTS', label: 'No Documents', icon: FileQuestion, count: noDocumentsCount },
          { id: 'ALL', label: 'All', icon: null, count: totalCount },
        ].map((tab) => {
          const Icon = tab.icon;
          const isActive = statusFilter === tab.id;
          return (
            <button
              key={tab.id}
              type="button"
              aria-pressed={isActive}
              onClick={() => setStatusFilter(tab.id as any)}
              className={`min-w-0 min-h-10 px-1.5 sm:px-4 py-2 rounded-full text-[11px] sm:text-xs font-bold font-display transition-all flex justify-center items-center gap-1 sm:gap-2 cursor-pointer ${tab.id === 'NO_DOCUMENTS' ? 'col-span-2' : ''} ${
                isActive
                  ? 'bg-[#0D0D11] text-white'
                  : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200 hover:text-zinc-900'
              }`}
            >
              {Icon && (
                <Icon className={`hidden sm:block w-3.5 h-3.5 shrink-0 ${isActive ? 'text-[#FFB380]' : 'text-zinc-400'}`} />
              )}
              <span>{tab.label}</span>
              <span className={`text-[10px] px-1.5 sm:px-2 py-0.5 rounded-full font-black ${
                isActive ? 'bg-[#FFB380] text-white' : 'bg-white text-zinc-600'
              }`}>
                {tab.count}
              </span>
            </button>
          );
        })}
      </div>

      {/* Requests Table or Empty State */}
      {filteredVerifications.length === 0 ? (
        <div className="py-16 flex flex-col items-center justify-center text-center my-auto">
          <div className="w-14 h-14 rounded-3xl bg-zinc-100 text-zinc-500 flex items-center justify-center mb-3">
            <CheckCircle className="w-7 h-7" />
          </div>
          <h4 className="text-base font-black font-display text-[#0D0D11]">
            {statusFilter === 'PENDING' 
              ? 'No Pending Requests' 
              : statusFilter === 'NO_DOCUMENTS'
              ? 'No Unsubmitted Users'
              : 'No Records Found'}
          </h4>
          <p className="text-xs text-zinc-400 max-w-xs mt-1 font-medium">
            {statusFilter === 'PENDING'
              ? 'All submitted documents in this category have been reviewed.'
              : statusFilter === 'NO_DOCUMENTS'
              ? 'All registered users in this category have submitted their verification documents.'
              : `There are currently no records matching the selected filters.`}
          </p>
          {statusFilter !== 'ALL' && (
            <button
              type="button"
              onClick={() => setStatusFilter('ALL')}
              className="mt-4 px-5 py-2 rounded-full bg-[#0D0D11] text-white text-xs font-bold font-display hover:bg-black transition-all cursor-pointer"
            >
              View All Applicants ({totalCount})
            </button>
          )}
        </div>
      ) : (
        <div className="overflow-x-auto mt-2">
          <table className="verification-applicants w-full text-left border-collapse min-w-[500px]">
            <thead>
              <tr className="text-[11px] font-bold uppercase tracking-wider text-zinc-400 font-display">
                <th className="py-2.5 px-2.5">User & Role</th>
                <th className="py-2.5 px-2.5">Documents</th>
                <th className="py-2.5 px-2.5">Submitted</th>
                <th className="py-2.5 px-2.5 text-right">Status</th>
              </tr>
            </thead>
            <tbody className="text-xs space-y-1">
              {paginatedVerifications.map((applicant) => {
                const item = applicant.user;
                const isSelected = item.id === selectedVerificationId || applicant.documents.some(document => document.id === selectedVerificationId);
                const isUnsubmitted = applicant.documents.length === 0;
                const isExpanded = expandedApplicantId === applicant.id;
                const toggleApplicant = () => {
                  setSelectedVerificationId(preferredDocument(applicant).id);
                  setExpandedApplicantId(isExpanded ? null : applicant.id);
                };
                const reviewApplicant = () => {
                  setExpandedApplicantId(applicant.id);
                  openComparisonModal(preferredDocument(applicant).id);
                };

                return (
                  <React.Fragment key={applicant.id}>
                  <tr
                    role="button"
                    tabIndex={0}
                    aria-expanded={isExpanded}
                    aria-controls={`applicant-documents-${applicant.id}`}
                    aria-label={`${item.name}, ${applicant.documents.length} documents. Open applicant review`}
                    onClick={reviewApplicant}
                    onKeyDown={event => { if (event.target === event.currentTarget && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); reviewApplicant(); } }}
                    className={`verification-applicant-row cursor-pointer transition-colors ${
                      isSelected
                        ? 'bg-zinc-100 text-zinc-950'
                        : 'hover:bg-zinc-50/80 text-zinc-700'
                    }`}
                    title="Open photo and document comparison"
                  >
                    {/* User & Role */}
                    <td className="py-2.5 px-2.5 rounded-l-2xl whitespace-nowrap">
                      <div className="flex items-center gap-2.5">
                        <button type="button" aria-label={`${isExpanded ? 'Collapse' : 'Expand'} documents for ${item.name}`} aria-expanded={isExpanded} onClick={event => { event.stopPropagation(); toggleApplicant(); }} className="shrink-0 rounded-lg p-1 text-zinc-400 hover:bg-zinc-200 focus-visible:ring-2 focus-visible:ring-orange-200">
                          <ChevronDown aria-hidden="true" className={`w-3.5 h-3.5 transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                        </button>
                        <div className="w-8 h-8 min-w-[32px] min-h-[32px] rounded-full overflow-hidden shrink-0 bg-zinc-100 flex items-center justify-center">
                          {item.avatar ? (
                            <img
                              src={getOptimizedWebpUrl(item.avatar, { width: 64, height: 64, quality: 'auto' })}
                              alt={item.name}
                              loading="lazy"
                              decoding="async"
                              className="w-full h-full object-cover"
                              onError={(e) => {
                                (e.target as HTMLElement).style.display = 'none';
                              }}
                            />
                          ) : (
                            <span className="font-bold text-xs text-zinc-500">
                              {item.name.slice(0, 2).toUpperCase()}
                            </span>
                          )}
                        </div>
                        <div className="min-w-0">
                          <div className="font-bold text-xs text-[#0D0D11] leading-tight">
                            {item.name}
                          </div>
                          <div className="flex flex-wrap items-center gap-x-1.5 gap-y-1 mt-1">
                            <span className="text-[10px] text-zinc-600 font-bold">
                              {item.barangay ? (item.barangay.toLowerCase().startsWith('brgy') ? item.barangay : `Brgy. ${item.barangay}`) : 'Brgy. Unassigned'}
                            </span>
                            <span className="text-[10px] text-zinc-300">•</span>
                            <span className="text-[10px] text-zinc-400 font-medium">
                              {item.role === 'KASAMBAHAY' ? 'Kasambahay' : item.role === 'HOMEOWNER' ? 'Homeowner' : item.role}
                            </span>
                            {item.hasLguCoverage === false && (
                              <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-md bg-amber-50 text-amber-700 border border-amber-200">
                                No LGU
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                    </td>

                    {/* Document Type (Consolidated Package or Single Doc or Unsubmitted) */}
                    <td data-label="Documents" className="py-2.5 px-2.5 whitespace-nowrap">
                      {isUnsubmitted ? (
                        <div className="flex items-center gap-1.5 text-zinc-400">
                          <FileQuestion className="w-3.5 h-3.5 text-amber-500 shrink-0" />
                          <span className="font-medium text-xs text-zinc-500 italic">
                            No Documents Uploaded
                          </span>
                        </div>
                      ) : (
                        <div className="flex items-center gap-1.5">
                          <FileText className="w-3.5 h-3.5 text-zinc-400 shrink-0" />
                          <span className="font-medium text-xs text-zinc-800">
                            {applicant.documents.length} {applicant.documents.length === 1 ? 'document' : 'documents'}
                          </span>
                        </div>
                      )}
                    </td>

                    {/* Submitted Date */}
                    <td data-label="Submitted" className="py-2.5 px-2.5 text-xs font-medium text-zinc-400 whitespace-nowrap" title={applicant.submittedDate}>
                      {isUnsubmitted ? '—' : applicant.submittedDate.split(' ').slice(0, 3).join(' ')}
                    </td>

                    {/* Status Pill (Minimal with dot indicator) */}
                    <td data-label="Status" className="py-2.5 px-2.5 text-right rounded-r-2xl whitespace-nowrap">
                      <VerificationStatusBadge status={applicant.status} />
                    </td>
                  </tr>
                  {isExpanded && (
                    <tr className="verification-document-details">
                      <td colSpan={4} className="px-2.5 pb-4 pt-2">
                        <div id={`applicant-documents-${applicant.id}`} aria-label={`Documents for ${item.name}`} className="rounded-2xl bg-zinc-50 p-3 space-y-2">
                          {isUnsubmitted ? <p className="p-2 text-xs text-zinc-500">No documents submitted yet.</p> : applicant.documents.map(document => (
                            <VerificationDocumentRow
                              key={document.id}
                              document={document}
                              selected={document.id === selectedVerificationId}
                              onReview={() => openComparisonModal(document.id)}
                              onApprove={approveVerification}
                              onReject={rejectVerification}
                              onReset={resetVerification}
                            />
                          ))}
                        </div>
                      </td>
                    </tr>
                  )}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Pagination Bar - Idiot-proof, edge-case safe, and responsive */}
      {filteredVerifications.length > 0 && (
        <div className="flex flex-col sm:flex-row items-center justify-between gap-3 pt-4 border-t border-zinc-100 mt-auto">
          {/* Left: Summary text */}
          <div className="text-xs text-zinc-500 font-medium">
            Showing <span className="font-bold text-zinc-900">{startIndex + 1}</span> to{' '}
            <span className="font-bold text-zinc-900">{endIndex}</span> of{' '}
            <span className="font-bold text-zinc-900">{totalRecords}</span> applicants
            {totalPages > 1 && (
              <span className="ml-2 text-zinc-400 font-normal">
                (Page {currentPage} of {totalPages})
              </span>
            )}
          </div>

          {/* Right: Pagination Controls */}
          <div className="verification-pagination flex flex-wrap justify-center items-center gap-1.5 select-none">
            {/* Previous Page */}
            <button
              type="button"
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
              disabled={currentPage === 1}
              className={`px-3 py-1.5 rounded-full text-xs font-bold transition-all flex items-center gap-1 border-0 ${
                currentPage === 1
                  ? 'bg-zinc-100 text-zinc-300 cursor-not-allowed pointer-events-none'
                  : 'bg-[#F0F0EC] text-zinc-700 hover:bg-[#E5E5E0] hover:text-zinc-950 cursor-pointer active:scale-95'
              }`}
              aria-label="Previous Page"
            >
              <ChevronLeft className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">Prev</span>
            </button>

            {/* Page Number Pills */}
            <div className="flex items-center gap-1">
              {getPageNumbers().map((page, idx) => {
                if (page === '...') {
                  return (
                    <span
                      key={`ellipsis-${idx}`}
                      className="w-7 h-7 flex items-center justify-center text-xs text-zinc-400 font-bold select-none"
                    >
                      ...
                    </span>
                  );
                }

                const pageNum = page as number;
                const isActive = pageNum === currentPage;
                return (
                  <button
                    key={pageNum}
                    type="button"
                    onClick={() => pageNum !== currentPage && setCurrentPage(pageNum)}
                    className={`w-7 h-7 rounded-full text-xs font-bold font-display transition-all flex items-center justify-center cursor-pointer border-0 ${
                      isActive
                        ? 'bg-[#0D0D11] text-white shadow-xs pointer-events-none'
                        : 'bg-[#F0F0EC] text-zinc-600 hover:bg-[#E5E5E0] hover:text-zinc-950 active:scale-95'
                    }`}
                    aria-label={`Page ${pageNum}`}
                    aria-current={isActive ? 'page' : undefined}
                  >
                    {pageNum}
                  </button>
                );
              })}
            </div>

            {/* Next Page */}
            <button
              type="button"
              onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
              disabled={currentPage === totalPages}
              className={`px-3 py-1.5 rounded-full text-xs font-bold transition-all flex items-center gap-1 border-0 ${
                currentPage === totalPages
                  ? 'bg-zinc-100 text-zinc-300 cursor-not-allowed pointer-events-none'
                  : 'bg-[#F0F0EC] text-zinc-700 hover:bg-[#E5E5E0] hover:text-zinc-950 cursor-pointer active:scale-95'
              }`}
              aria-label="Next Page"
            >
              <span className="hidden sm:inline">Next</span>
              <ChevronRight className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import type { VerificationStatus } from '../../types/admin';

export const VerificationStatusBadge: React.FC<{ status: VerificationStatus }> = ({ status }) => {
  const colors = status === 'VERIFIED' ? 'bg-emerald-50 text-emerald-700'
    : status === 'EXPIRED' ? 'bg-orange-100 text-orange-800'
    : status === 'REJECTED' ? 'bg-rose-50 text-rose-700'
    : status === 'NO_DOCUMENTS' ? 'bg-zinc-100 text-zinc-500' : 'bg-amber-50 text-amber-800';
  const label = status === 'VERIFIED' ? 'Verified' : status === 'REJECTED' ? 'Rejected'
    : status === 'EXPIRED' ? 'Expired'
    : status === 'NO_DOCUMENTS' ? 'No documents' : 'Pending Review';
  return <span className={`inline-flex rounded-full px-2.5 py-1 text-[11px] font-medium whitespace-nowrap ${colors}`}>{label}</span>;
};

